  'f360.tile.creditKycYes': 'દરેક સક્રિય ભૂમિકા પર KYC ચકાસાયેલ',
  'f360.tile.creditKycNo': 'દરેક સક્રિય ભૂમિકા પર KYC પૂર્ણ નથી',
  'f360.tile.creditAbsent': 'અમે ધિરાણ-તૈયારીનો આંક આપતા નથી. કોઈ ધિરાણકર્તાએ અમારી સાથે નિયમ નક્કી કર્યો નથી, અને સભ્યને લોન-તૈયાર કહીને બેન્ક ના પાડે તો તેમનો એક દિવસનો રોજ જાય છે. બેન્કરને ઉપરના પુરાવા આપો.',
  'f360.seasons': 'ઋતુ સમયરેખા',
  'f360.noSeasons': 'આ સભ્ય માટે હજી કોઈ પાક ઋતુ નોંધાયેલી નથી.',
  'f360.seasonsNote': 'શું વાવ્યું અને લણ્યું. વેચાણ ઋતુ સામે દેખાડાતું નથી: રેકોર્ડમાં કોઈ કડી કોઈ ઓર્ડરને કોઈ વાવણી સાથે જોડતી નથી, અને અનુમાનથી જોડવું બંનેને ખોટાં ઠરાવે.',
