  'listingManage.archiveHeading': 'જોખમ ક્ષેત્ર — આર્કાઇવ',
  'listingManage.archiveNote': 'આર્કાઇવ કરવાથી લિસ્ટિંગ દરેક ખરીદદાર સપાટીથી કાયમ માટે હટે છે (આર્કાઇવમાંથી પાછા ફરવાનું નથી). સ્ટાફ સભ્યની લિસ્ટિંગ આર્કાઇવ કરે તો સભ્યને કારણ તેમની ભાષામાં જણાવાય છે.',
