  'listingNew.errorHarvest': 'કાપણીની તારીખ સાચી તારીખ (YYYY-MM-DD) હોવી જોઈએ — અથવા ખાલી છોડો. કંઈ સચવાયું નથી; તમારાં મૂલ્યો સચવાયેલાં છે.',
  'listingNew.consent': 'આ સભ્યે સ્ટાફ દ્વારા તેમના વતી લિસ્ટ કરવાની સંમતિ નોંધાવી નથી — કંઈ બન્યું નથી. તેમની ઉપજ, તેમની હા.',
  'listingNew.consentHow': 'સભ્ય એક વાર on-behalf સંમતિ આપે છે (અવાજ કે ઍપ ટૅપ, હેતુ "on_behalf_listing") — એ જ નોંધાયેલી હા જે એમ્બેસેડર વાપરે છે. તેમને ઍપમાં પુષ્ટિ કરવા કહો, પછી ફરી બનાવો.',
  'listingNew.onBehalfHeading': 'સભ્ય વતી લિસ્ટિંગ',
  'listingNew.onBehalfChosen': 'આમના માટે લિસ્ટિંગ: {name}. કંઈ પણ બનાવતા પહેલાં સર્વર તેમની નોંધાયેલી સંમતિ તપાસે છે.',
  'listingNew.onBehalfClear': 'હટાવો',
  'listingNew.onBehalfSearch': 'સભ્ય શોધો (તેમની ઉપજ, લિસ્ટિંગ પર તેમનું નામ)',
  'listingNew.onBehalfNone': 'કોઈ સભ્ય મળ્યા નહીં. People પાનું જુઓ — રોસ્ટર શોધ એ જ છે.',
  'listingNew.onBehalfConsentNote': 'પહેલા સભ્ય પસંદ કરો — તેમની ચકાસાયેલી પ્રોફાઇલ જ કહે છે કે ઉપજ કોની છે. તેમની નોંધાયેલી સંમતિ વિના નિર્માણ નામંજૂર છે.',
  'listingNew.harvestLabel': 'કાપણીની તારીખ',
  'listingNew.harvestHint': 'વૈકલ્પિક — આ લોટ ક્યારે કપાયો. ખરીદદારો સંગ્રહેલા પાકની ઉંમર પ્રામાણિકપણે જુએ છે.',
  'listingNew.checkBand': 'વાજબી-ભાવ બૅન્ડ જુઓ',
  'listingNew.bandRow': 'સાથી બૅન્ડ {low}–{high} (મધ્ય {modal}) — આ જ સંસ્થાની પોતાની પ્રકાશિત લિસ્ટિંગનો P10–P90, એ જ ઉત્પાદન અને વિસ્તાર, {n} લિસ્ટિંગ પર. બૅન્ડ બહારનો ભાવ સંકેત છે, અટકાવ નહીં.',
  'listingNew.bandNone': 'કોઈ સાથી બૅન્ડ નથી: આ વિસ્તારમાં આ ઉત્પાદનની સરખાવી શકાય તેવી પ્રકાશિત લિસ્ટિંગ હજી નથી — અજાણ્યું, તમારા ભાવ પર ચુકાદો નહીં.',
  'listingNew.bandNoRegion': 'આ પિનકોડ કોઈ જાણીતા વિસ્તાર સાથે જોડાતો નથી — બૅન્ડ જોઈ શકાતો નથી. પિનકોડ તપાસો.',
  'listingNew.mediaPreserved': 'અગાઉ અપલોડ કરેલા {n} ફોટા આ ફોર્મ સાથે સચવાયેલા છે.',
  'listingNew.submitOnBehalf': 'આ સભ્ય માટે ડ્રાફ્ટ બનાવો',
  'listingNew.reviewNote': 'બનાવવાથી ડ્રાફ્ટ બને છે અને તેના પાના પર પહોંચો છો — એ જ પાનું સબમિટ પહેલાંની સમીક્ષા છે (QCની મંજૂરી કે તમારા પ્રકાશન સુધી કંઈ ખરીદદારો સુધી પહોંચતું નથી).',

  /* ==================== PC-56 TENANT-2c · bulk listing upload (W128 + W2355–W2356) ==================== */
  'limport.title': 'લિસ્ટિંગ બલ્ક અપલોડ',
  'limport.subtitle': 'CSV કે Excel — એક લોટ માટે એક પંક્તિ. કંઈ પણ બનતાં પહેલાં દરેક પંક્તિ ચકાસાય છે; એક ખરાબ પંક્તિ સારી પંક્તિઓને રોકતી નથી.',
  'limport.trustPath': 'બલ્કથી બનેલી લિસ્ટિંગ સામાન્ય રસ્તે જ ચાલે છે: ડ્રાફ્ટ → સભ્યની સંમતિ → QC → પ્રકાશિત. બલ્ક નોંધણી ઝડપી કરે છે, ભરોસો છોડતું નથી — સમીક્ષકની મંજૂરી વગર કંઈ ખરીદદાર સુધી પહોંચતું નથી.',
  'limport.consentNote': 'દરેક પંક્તિ બીજાની ઉપજ છે, તેથી દરેક સભ્યની on-behalf સંમતિ નોંધાયેલી હોવી જોઈએ (અવાજ કે ઍપ ટૅપ). જેમાં નથી તે સુધારા માટે ચિહ્નિત થાય છે — ચૂપચાપ કાઢી નખાતી નથી. તેમની ઉપજ, તેમની હા.',
  'limport.kycGap': 'કૅનનનું “KYC બાકી — ડ્રાફ્ટ ચાલે, પ્રકાશન ચકાસણી સુધી અટકે” ઈરાદાપૂર્વક અડધું બનેલું છે: ડ્રાફ્ટ બને છે, પણ આ પ્લેટફોર્મ પર પ્રકાશન પર કોઈ KYC ગેટ ક્યાંય નથી (પ્રતિ-ભૂમિકા KYC નકશો ચુકવણી માટે છે, લિસ્ટિંગ માટે નહીં). અહીં ગેટ ઘડવો એ નિયમ ફક્ત આયાત થયેલા લોટ પર લાગુ કરે — તેથી તેને બૅકએન્ડ કામ તરીકે નામ આપ્યું, ઘડ્યું નહીં.',
  'limport.templateHeading': 'ટેમ્પ્લેટ',
  'limport.templateNote': 'કૉલમ: {columns}. જે યાદી ઇમ્પોર્ટર વાંચે છે તેમાંથી જ બને છે, તેથી ટેમ્પ્લેટ પાર્સરથી અલગ પડી શકતું નથી.',
  'limport.templateRequired': 'ફક્ત phone (કોની ઉપજ) અને product (શું) ભરવું જરૂરી છે — બાકીની ગેરહાજરી સ્વાભાવિક છે. ભાવ પ્રતિ એકમ છે; unit કૉલમ નક્કી કરે છે કઈ. પ્રતિ-ક્વિન્ટલ શીટ પર પ્રતિ-કિલો ભાવ પકડાય છે અને સુધારો સૂચવાય છે.',
