  'limport.error.failed': 'ફાઇલ વાંચી જ ન શકાઈ (ફોર્મેટ, ખૂટતા કૉલમ, કે અપલોડ અનુપલબ્ધ). કંઈ બન્યું નથી.',
  'limport.idempotentNote': 'એ જ ફાઇલ ફરી અપલોડ કરવાથી બમણું બનતું નથી: દરેક પંક્તિ પોતાના લોટ (સભ્ય + ઉત્પાદન + જથ્થો + ભાવ) થી ઓળખાય છે, તેથી એક ફાઇલમાં એ જ લોટ બે વાર એક જ ડ્રાફ્ટ છે.',

