  'od.tdsNote': 'TDS વિશે એક વાત, કારણ કે કલમ મહત્ત્વની છે: આ પ્લેટફોર્મ 194-O હેઠળ કપાત કરે છે (માર્કેટપ્લેસ સંચાલકની કપાત, વેચનારના કુલ પર) અને તે સેટલમેન્ટ સમયે થાય છે — તે સેટલમેન્ટ સ્ટેટમેન્ટ પર દેખાય છે, ઓર્ડર પંક્તિ પર નહીં. કલમ 194Q ખરીદદારની પોતાની કપાત છે (વાર્ષિક મર્યાદાથી વધુ ખરીદી પર) અને તે તેમની ફાઇલિંગ છે, અમારી નહીં. અહીં ₹0 એટલે ઓર્ડર સમયે કોઈ કપાત લાગુ નહીં — એ નહીં કે કપાત માફ થઈ.',

