  'dsp.machine': 'સાત સ્થિતિ: open → seller_responded → under_review → escalated / resolved / rejected / withdrawn. વિવાદ ઓર્ડરને થોભાવે છે; નિર્ણય માણસનો હોય છે અને નોંધાય છે.',
  'dsp.freezeTruth': 'વિવાદ ખુલ્લો હોય ત્યાં સુધી આખા ઓર્ડરની ખરીદદાર-ચુકવણી એસ્ક્રોમાં રોકાયેલી રહે છે — ફક્ત વિવાદિત ભાગ નહીં. પ્રતિ-લાઇન રિલીઝ હજી બન્યું નથી, તેથી બિન-વિવાદિત ભાગ પણ રોકાય છે. આ પાનું જે ખરેખર રોકાયું છે તે બતાવે છે.',
