  'dsp.basis.escrowGross': 'આ ઓર્ડરની ખરીદદાર-ચુકવણી પ્લેટફોર્મ એસ્ક્રોમાં છે — આખી. આ પ્લેટફોર્મ બિન-વિવાદિત ભાગ વહેલો છોડતું નથી.',
  'dsp.basis.settledBefore': 'વિવાદ આવ્યો તે પહેલાં આ ઓર્ડર વેચનારને સેટલ થઈ ગયો હતો, તેથી કંઈ રોકાયું નથી: રિફંડ સેટલમેન્ટને પગલે-પગલે પાછું ખેંચે છે અને પૈસા ઉપાડી લેવાયા હોય તો નિષ્ફળ જઈ શકે.',
