  'inv.title': 'વેપાર બિલ (ઇનવોઇસ)',
  'inv.saasLink': 'સબસ્ક્રિપ્શન બિલ →',
  'inv.sub': 'ખરીદદાર માટે GST ઇનવોઇસ, પ્રતિ ઓર્ડર એક — તમારા સબસ્ક્રિપ્શન બિલથી અલગ. કુલ એ જ છે જે ખરીદદારે ચૂકવ્યું: દર્શાવેલ ટેક્સ તેમાં સમાયેલો છે, ઉપરથી ઉમેરાયો નથી.',
  'inv.needsFinance': 'આ દૃશ્ય માટે report.view પરવાનગી (ફાઇનાન્સ સ્કોપ) જોઈએ. ખરીદદાર/વેચનાર પોતાનું ઇનવોઇસ ઓર્ડરમાંથી હંમેશા જોઈ શકે.',
