  // PC-56 TENANT-4c · W147/W148 — the settlement cycle and the statements it produces.
  'stl.title': 'Settlement',
  'stl.intro': 'Darek vikreta na settlement cycle: kul vechan − commission − tax = chokhkhu chukavayu. Cycle band karvu e ek galaa na vyapaar ne eva statement ma badle chhe je tamara sabhyo hath ma rakhi shake, ane ema be manas joie.',
  'stl.restricted': 'Settlement cycle mate settlement.close paravangi joie. Admin ne kaho — cycle par kai asar nathi.',
  'stl.loadError': 'Cycle load na thayu. Gala ma kai badlayu nathi. Fari prayatna karo.',
  'stl.noCycle': 'Have koi cycle khulyu nathi. Tamaru pehlu vechan ena gala ma nipte tyare cycle khuli jaay chhe.',
  'stl.currentCycle': 'Chalu cycle',
  'stl.cycleGrossHint': '{sellers} vikreta jena vechan have nipata nathi · {period}',
  'stl.status.open': 'khullu',
  'stl.status.pending_close': 'biji vyakti ni raah',
  'stl.status.closing': 'band thai rahyu — statement bane chhe',
  'stl.status.closed': 'band',
  'stl.status.rejected': 'band karvu nakaryu',
  'stl.status.unknown': 'ajani sthiti',
  'stl.progressTitle': 'Statement',
  'stl.progress.notStarted': 'Have koi statement nathi. Biji vyakti ni manjuri pachi banva lage chhe.',
  'stl.progress.generating': '{expected} ma thi {generated} banya · {remaining} baaki',
  'stl.progress.complete': 'Badha {generated} statement bani gaya.',
  'stl.progress.overGenerated': '{expected} apekshit hata pan {generated} statement chhe. Manjuri pachi koi vikreta na vechan umerayela — kona te jovu saru.',
  'stl.progressHint': 'Darek statement potanu alag transaction chhe, tethi vachche nishfalta ek vikreta na fari prayatna jetli chhe, aakha gala ni nahi. E j karane ahi ganatri dekhay chhe, "badhu ek j sathe" no daavo nahi: ek lakh vikreta nu ek j transaction koi pan database pase magvu yogya nathi.',
  'stl.signatures': 'Sahi',
  'stl.notRequested': 'Aa cycle mate band karva ni koi vinanti thai nathi.',
  'stl.requestedAt': 'Band karva ni vinanti {at}',
  'stl.decidedAt': 'Nirnay {at}',
  'stl.twoHumans': 'Cycle band karva ma sada be manas joie: ek vinanti kare, biji manjuri aape. Evi koi rakam nathi jena niche ek vyakti puro hoy — cycle koina rozgaar no galo chhe, fakt aankdo nahi.',
  'stl.closeTitle': 'Aa cycle band karo',
  'stl.requestConfirm': 'Aa cycle band karva ni vinanti: {sellers} vikreta, {gross} kul vechan. Pachi bijo admin manjuri aape, ane tya pachi statement bane.',
  'stl.requestClose': 'Band karva ni vinanti',
  'stl.closeBlocked.noPermission': 'Cycle band karva mate settlement.close paravangi joie.',
  'stl.closeBlocked.notOpen': 'Aa cycle khullu nathi — ke band thai rahyu chhe ke thai gayu chhe.',
  'stl.closeBlocked.periodNotEnded': 'Aa cycle no chhello divas have puro thayo nathi. Vehela band karva thi aaj na vechan e gala thi bahar rahi jashe jena te chhe, ane vikreta ne khabar pan nahi pade ke kaya statement ma gaya.',
  'stl.closeBlocked.nothingToSettle': 'Aa gala ma koi baaki vechan nathi, tethi band karva jevu kai nathi.',
  'stl.youRequested': 'Tame aa vinanti kari hati, tethi tame j manjuri aapi shako nahi. Bija admin pase sahi karavo — tamari vinanti tame nakari shako chho.',
  'stl.approveConfirm': '{sellers} vikreta mate band karva ni manjuri aapo. Tya pachi darek vikreta nu ek statement bane chhe.',
  'stl.approveClose': 'Band karva ni manjuri',
  'stl.noteOptional': 'Nondh (vaikalpik)',
  'stl.rejectNote': 'Aa band karvu kem nakaro chho? Vinanti karnar ne kahevashe.',
  'stl.rejectNoteHint': 'Kam ma kam {floor} akshar. Cycle fari khulu thai jaay chhe ane karan ukelaya pachi fari vinanti thai shake.',
  'stl.rejectClose': 'Karan sathe nakaro',
  'stl.generate': 'Statement banavo',
  'stl.generateHint': 'Aa cycle na aagla statement banavo. Baaki dekhay tya sudhi fari dabavo — kaam tya thi aagal vadhe chhe, sharu thi nahi, tethi moto tenant kai tabakka ma pura thay chhe, ek moto transaction ma nahi.',
  'stl.sellersTitle': 'Aa cycle na vikreta',
