  'stl.netMismatch': 'jodo malto nathi',
  'stl.deduction.buyer': 'Commission ane tax ₹0 dekhay chhe karan ke tamari sanstha KHARIDNARO pase thi le chhe, vikreta pase thi nahi — tethi vikreta potanu aakhu kul rakhe chhe. Column etla mate chhe ke vikreta-paksh sanstha ne ema saachi katotri dekhay.',
  'stl.deduction.seller': 'Tamari sanstha VIKRETA pase thi le chhe, tethi darek vikreta na kul ma thi katayel commission ane tax aa column ma dekhay chhe.',
  'stl.deduction.noRule': 'Tamari sanstha mate koi sakriya commission niyam malyo nathi, tethi aa column ₹0 dekhade chhe karan ke kai nakki thayu nathi — etla mate NAHI ke kharidnar bhare chhe. Aa alag vaato chhe, ane cycle band karva pehla aa set karvu joie.',
  'stl.legacyDaily': 'Tamara {count} statement raat na job e DAINIK dastavej tarike banavya hata, jyare cycle astitva ma j nahoti. Tene evu j batavyu chhe, cycle statement nu naam apyu nathi.',
