  'stl.ok.requested': 'Band karva ni vinanti nondhai. Have bijo admin manjuri aapi shakshe.',
  'stl.ok.approved': 'Band karvu manjur. Statement bane chhe — ganatri jate vadhti dekhashe.',
  'stl.ok.rejected': 'Band karvu nakaryu, cycle fari khulu. Vinanti karnar ne karan kahi didhu.',
