  'stl.colIssued': 'Jari',
  'stl.period.cycle': 'cycle · {days} divas',
  'stl.period.daily': 'dainik dastavej · {days} divas',
  'stl.pdf.ready': 'taiyar',
  'stl.pdf.notRendered': 'have banyu nathi',
  'stl.mixedPeriods': '{cycle} statement ek cycle na chhe; {daily} e vakhat na dainik dastavej chhe jyare cycle nahoti. Galo column kahe chhe kon kayu chhe.',
  'stl.orgStatementTitle': 'Sanstha nu mahina nu statement',
  'stl.orgStatementDerived': 'Aa statement darek vakhat tamara append-only ledger mathi BANAVAY chhe — sharu no balance, prakar pramane halchal, chhello balance — ane aa tran no mel na hoy to jari thatu j nathi. Ena koi statement number nathi, karan ke te sacheli copy nathi: jene te j ledger rows hoy te tene barabar evu j fari banavi shake, je file ma rakhel PDF thi vadhu majbut guarantee chhe — kem ke te PDF ne ledger pachi khoto pan thabhavi shake.',
  'stl.orgStatementMonth': 'Mahino',
  'stl.orgStatementOpenMonth': 'Fakt pura thayela mahina apay chhe: chalu mahina nu statement bank manager ne aapya pachi badlay chhe.',
  'stl.orgStatementDownload': 'Statement download karo',
