  'freight.settle.nextCycle': "સ્વીકારેલી લાઇનો આગલા ચક્રમાં ચૂકવાય અને પાછી ખેંચેલી લાઇનો ક્રેડિટ નોટથી બંધ થાય. બંને અહીં નથી: લાઇન પતાવવાથી સ્વીકારેલી રકમ નોંધાય છે અને કોઈ દસ્તાવેજ નીકળતો નથી.",
