  'dairy.centres.gap.heading': "આ બોર્ડ હજી શું કરી શકતું નથી",
  'dairy.centres.gap.transfer': "અહીંથી સભ્યપદ એક કેન્દ્રથી બીજા કેન્દ્રે મોકલી શકાતું નથી. મોકલવું સહેલું છે; ઇતિહાસ સાચો રાખવો નથી — બંધ થયેલા પખવાડિયાનું રજિસ્ટર બિલનું કેન્દ્ર આજના માર્ગ પરથી વાંચે છે, તેથી પહેલી જ બદલી દરેક જૂના ચક્રનું શ્રેય બદલી નાખે. આ સુવિધા એ વાચનના સુધારા સાથે આવશે.",
  'dairy.centres.gap.hoursHistory': "પાળીના સમયનો કોઈ ઇતિહાસ નથી. સહકારી પોતાની સાંજની પાળી બદલે ત્યારે જૂનો સમય જતો રહે છે — કોઈ જૂના રેકોર્ડનો પુનર્નિર્ણય થતો નથી, પણ \"જૂનમાં આ કેન્દ્ર કેટલા વાગ્યે ખૂલતું\" તેનો જવાબ મળી શકતો નથી.",
  'dairy.centres.gap.reliefOperator': "એક સમયે કેન્દ્રની જવાબદારી એક જ વ્યક્તિની હોય છે. જે સહકારી બે પાળીમાં બે ઑપરેટર ખરેખર રાખે છે, તેનું મોડેલ બન્યું નથી, અને અહીં બીજું નામ એવું ખાનું બનશે જેમાં કંઈ લખાતું જ નથી.",

