  'dairy.centres.move.refusal.CODE_TAKEN': "એ કેન્દ્ર પર આ કાર્ડ નંબર પહેલેથી બીજા સભ્ય પાસે છે.",
  'dairy.centres.move.refusal.CODE_HELD_AT_DESTINATION': "આ સમયગાળામાં એ કાર્ડ નંબર એ કેન્દ્ર પર બીજા કોઈ પાસે હતો. એક જ અઠવાડિયે બે ખેડૂત પાસે એક કાર્ડ હોવું એવી ખોટી પરચી છે જેને પછી કોઈ ઉકેલી શકતું નથી.",
  'dairy.centres.move.refusal.BEFORE_LAST_POUR': "આ સભ્યે એ તારીખે કે પછી પોતાના વર્તમાન કેન્દ્ર પર દૂધ આપ્યું છે. પરચી કહે છે તેઓ ક્યાં ઊભા હતા; રેકોર્ડ તેની વિરુદ્ધ ન જઈ શકે.",
  'dairy.centres.move.refusal.BEFORE_ROUTE_START': "એ તારીખ આ સભ્યપદ પોતાના વર્તમાન કેન્દ્રે આવ્યું તે દિવસ પહેલાંની છે.",
  'dairy.centres.move.refusal.NO_CURRENT_ROUTE': "આ સભ્યપદનો કોઈ વર્તમાન માર્ગ નોંધાયેલો નથી, તેથી મોકલવા જેવું કંઈ નથી. મોકલવાને બદલે કોઈને જણાવો.",
  'dairy.centres.move.caution.SPLITS_OPEN_CYCLE': "આ તારીખે એક ચુકવણી ચક્ર ખુલ્લું છે, તેથી આ પખવાડિયાના બિલમાં બે કેન્દ્રોનું દૂધ આવશે. એ સાચું છે — દરેક પરચી જાણે છે તે ક્યાં બની — અને રજિસ્ટર બંને ગામ જણાવશે.",
  'dairy.centres.move.caution.UNBILLED_POURS_AT_OLD_CENTRE': "જૂના કેન્દ્ર પર કેટલીક પરચીઓનું બિલ હજી બન્યું નથી. તે આ જ સભ્યપદ સાથે રહેશે અને સામાન્ય રીતે બિલમાં આવશે.",
  'dairy.centres.move.caution.DEBT_FOLLOWS_MEMBER': "આ સભ્યની કપાત વ્યવસ્થાઓ ચાલુ છે. દેવું વ્યક્તિ સાથે ચાલે છે, ગામ સાથે નહીં — કેન્દ્ર બદલવાથી તે પૂરું થતું નથી.",
  'dairy.centres.ok.moved': "સભ્યપદ મોકલાયું. જૂનો માર્ગ એક દિવસ પહેલાં બંધ અને નવો અમલી તારીખથી ખૂલ્યો.",
