  'mutate.bmc.refusal.NOBODY_HOLDS_CENTRE': "આ કેન્દ્રની જવાબદારી કોઈની પાસે નથી, તેથી કૉલ કરવા માટે કોઈ ઑપરેટર નથી. કેન્દ્ર સ્ક્રીન પર કોઈને સોંપો — જવાબદાર વગરનું કેન્દ્ર ગરમ ટાંકી કરતાં મોટી સમસ્યા છે.",
