  'dairy.bmc.call.notEnabled': "આ સ્ક્રીનથી ઑપરેટરને કૉલ કરવાનું તમારી સહકારી માટે ચાલુ નથી. અલર્ટ પર તેની અસર નથી — તે આના પર આધારિત નથી.",
  'dairy.bmc.alerting.noSilenceRule': "સેન્સરની ચુપકીદી પર નજર રાખતો કોઈ નિયમ નથી, તેથી આ સ્ક્રીન ગૅપ બતાવે છે અને કોઈને કૉલ જતો નથી. બદલવા માટે silent-device નિયમ ઉમેરો.",
  'dairy.bmc.alerting.silenceRuleDiffers': "જે નિયમ કોઈને બોલાવે છે તેની મર્યાદા આ સ્ક્રીનના ગૅપથી અલગ છે — બંને વાજબી છે, પણ ફોન એક જ વગાડે છે.",
