  'dairy.bmc.alerting.silenceRuleAt': "આટલી મિનિટની ચુપકીદી પછી કોઈને કૉલ જાય છે:",
  'dairy.bmc.alerting.checkedEvery': "તપાસ દર (મિનિટ):",
  'dairy.bmc.alerting.criticalNotCatalogued': "આ ડિપ્લોયમેન્ટ પર ગંભીર અલર્ટ કોઈને જગાડી શકતું નથી: ગંભીર અલર્ટની ઘટના સૂચિબદ્ધ નથી, તેથી શાંત કલાકોમાં સવાર સુધી દરેક ફોન ચૅનલ ચૂપ રહે છે.",
