  'dairy.insights.lead': "છેલ્લા નેવું દિવસમાં તમારી સહકારીના પોતાના રેકોર્ડ શું કહે છે — અને જ્યાં આ પ્લૅટફૉર્મ કંઈ જાણી જ શકતું નથી, ત્યાં જવાબ જેવો દેખાતો આંકડો નહીં, પણ શું ખૂટે છે એ.",
  'dairy.insights.window.label': "સમયગાળો",
  'dairy.insights.window.30': "30 દિવસ",
  'dairy.insights.window.90': "90 દિવસ",
  'dairy.insights.window.180': "180 દિવસ",
  'dairy.insights.state.ok': "અંતર્દૃષ્ટિ તૈયાર છે.",
  'dairy.insights.state.notEnabled': "તમારી સહકારી માટે અંતર્દૃષ્ટિ ચાલુ નથી. તમારા રેકોર્ડમાં કંઈ ખૂટતું નથી — આ પાનું ફક્ત બંધ છે, અને તમારું સંગ્રહ, બિલ તથા ચક્ર અકબંધ છે.",
  'dairy.insights.state.unavailable': "અંતર્દૃષ્ટિ બનાવી શકાઈ નથી. આ પાનાનો દરેક આંકડો પ્રતિ લિટર પૈસા છે, અને તમારી સહકારીનું ચલણ કે તેના દશાંશ સ્થાનની સંખ્યા નોંધાયેલી નથી — તેથી ખોટું બતાવવાને બદલે કંઈ બતાવ્યું નથી.",
  'dairy.insights.state.noData': "હજી કોઈ દૂધ નોંધાયું નથી, તેથી સરખાવવા જેવું કંઈ નથી. સંગ્રહનું પહેલું ચક્ર આ પાનું ભરી દેશે.",
  'dairy.insights.state.notEnoughHistory': "હજી પૂરતો ઇતિહાસ નથી. અહીંનો દરેક આંકડો સરખામણી છે, અને એક ચક્રની સરખામણી કોઈ સાથે થઈ શકતી નથી — બે પૂરાં ચક્ર જોઈએ.",
  'dairy.insights.state.restricted': "ડેરી અંતર્દૃષ્ટિ સુધી તમારી પહોંચ નથી. તમારી સહકારીના વ્યવસ્થાપક પાસે ડેરી ડેસ્કનો અધિકાર માંગો.",
  'dairy.insights.state.error': "અંતર્દૃષ્ટિ લોડ થઈ શકી નથી. તમારું સંગ્રહ અને બિલ અકબંધ છે — આ પાનું તેમને ફક્ત વાંચે છે.",
