  'dairy.insights.pourers.lookback': "\"નવા\" અને \"પાછા આવ્યા\" છેલ્લા આટલા દિવસના આધારે ગણાય છે:",
  'dairy.insights.pourers.none': "આ સમયગાળામાં કોઈએ દૂધ ભર્યું નથી.",
  'dairy.insights.pourers.inconsistent': "આ ગણતરીઓ મળતી નથી, તેથી બતાવી નથી. આ પ્લૅટફૉર્મની ખામી છે, તમારા રેકોર્ડની નહીં — કૃપા કરીને જાણ કરો.",
  'dairy.insights.pourers.soFar': "અત્યાર સુધી દૂધ ભરનારા",
