  'dairy.insights.payout.instead': "આ પ્લૅટફૉર્મ દરેક ચક્રના પૈસાનો વચનનો દિવસ નોંધે છે, પહોંચ્યાનો દિવસ કદી નહીં — તેથી સમયસર ચુકવણીની કડી ગણી શકાતી નથી. જે જાણીતું છે:",
