  'dairy.insights.chart.caption': "પ્રતિ સપ્તાહ લિટર, પાળી પ્રમાણે. જે સપ્તાહે સંગ્રહ ન થયો હોય તે શૂન્ય બતાવ્યું છે, છોડી દીધું નથી.",
  'dairy.insights.chart.week': "સપ્તાહ શરૂ",
  'dairy.insights.chart.total': "કુલ",
  'dairy.insights.chart.partial': "અધૂરું સપ્તાહ",
  'dairy.insights.moved.title': "પ્રતિ લિટર દર શેનાથી બદલાયો",
  'dairy.insights.premium.title': "ગુણવત્તા પ્રીમિયમ",
  'dairy.insights.premium.noSlabs': "તમારું દર કાર્ડ કોઈ ગુણવત્તા પ્રીમિયમ આપતું નથી, તેથી પ્રીમિયમ શ્રેણી નથી. એ ભાવ નક્કી કરવાનો નિર્ણય છે, દૂધની ખામી નહીં.",
  'dairy.insights.premium.noPours': "આ સમયગાળામાં દૂધ નથી, તેથી કોઈ સભ્ય પ્રીમિયમ શ્રેણી સુધી પહોંચી શક્યો નથી.",
  'dairy.insights.premium.earned': "જે સભ્યોને ખરેખર પ્રીમિયમ મળ્યું:",
  'dairy.insights.premium.wouldQualify': "પ્રીમિયમ શ્રેણીઓ બંધ છે, તેથી કોઈને પ્રીમિયમ મળ્યું નથી. જે સભ્યોનું દૂધ પાત્ર થયું હોત:",
  'dairy.insights.premium.was': "પહેલાં હતું",
  'dairy.insights.premium.basisChanged': "આગલા સમયગાળા સાથે સરખામણી નથી: બંને વચ્ચે પ્રીમિયમ શ્રેણીઓ ચાલુ કે બંધ થઈ છે, અને એ તમારી સેટિંગનો ફેર છે, દૂધનો નહીં.",
  'dairy.insights.premium.basisUnknown': "આગલા સમયગાળા સાથે સરખામણી નથી: હવે પ્રીમિયમ અપાય છે, અને એ સમયગાળામાં કંઈ અપાયું નહોતું. ત્યારે ગુણવત્તા શ્રેણીઓ બંધ હતી, કે ચાલુ હતી પણ કોઈ સભ્ય શ્રેણી સુધી પહોંચ્યો નહોતો — એ આ પ્લૅટફૉર્મ પર ક્યાંય નોંધાયું નથી, તેથી અહીં કોઈ દાવો કરાયો નથી.",
  'dairy.insights.premium.noPrevious': "આ પહેલાં સરખાવી શકાય એવો સમયગાળો નથી.",
  'dairy.insights.premium.paid': "આ સમયગાળામાં ખરેખર આપેલું પ્રીમિયમ:",
  'dairy.insights.premium.metric.fat': "ફૅટ",
  'dairy.insights.premium.metric.snf': "એસએનએફ",
  'dairy.insights.rateCard.title': "લાગુ દર કાર્ડ",
  'dairy.insights.rateCard.noVersion': "આ પ્લૅટફૉર્મ પર દર કાર્ડનો કોઈ આવૃત્તિ ક્રમાંક હોતો નથી — ફક્ત લાગુ થવાની તારીખ — તેથી તેમને તેમના નામ અને એ તારીખથી ઓળખાવ્યા છે.",
  'dairy.insights.rateCard.effective': "લાગુ",
  'dairy.insights.rateCard.pricingNow': "આજના દૂધનો ભાવ નક્કી કરે છે",
  'dairy.insights.rateCard.ambiguous': "આ પશુ પ્રકાર માટે એકસાથે બે કાર્ડ લાગુ છે, કારણ કે જૂનું બંધ કરાયું નથી. જે પછી શરૂ થાય તે ચૂપચાપ દરેક દૂધનો ભાવ નક્કી કરે છે. શંકા દૂર કરવા જૂના કાર્ડની અંતિમ તારીખ ભરો.",
  'dairy.insights.spoilage.title': "બગડેલું દૂધ",
  'dairy.insights.drillDown.allowed': "તમે આ પાનેથી કોઈ સભ્યનો પોતાનો રેકોર્ડ ખોલી શકો છો.",
  'dairy.insights.drillDown.restricted': "આ કુલ આંકડા તમે વાંચી શકો છો; એક સભ્યનો પોતાનો રેકોર્ડ ખોલવા સભ્ય 360 પરવાનગી જોઈએ, જે અલગથી અપાય છે.",
  'dairy.insights.derivedFootnote': "અહીંનો દરેક આંકડો તમારા સંગ્રહ, બિલ અને ચુકવણી ચક્રમાંથી બનેલો છે. કોઈ અલગ વિશ્લેષણ કોષ્ટક રખાતું નથી, તેથી આ પાનાનું કંઈ પણ તમારા રેકોર્ડથી અલગ પડી શકતું નથી.",

  // PC-56 TENANT-6e-2 · W2553 (export queued) + W2554 (export ready) — the export plane
  'dairy.export.breadcrumb': "માર્ગ",
  'dairy.export.title.queued': "નિકાસ કતારમાં",
  'dairy.export.title.ready': "નિકાસ તૈયાર",
  'dairy.export.title.failed': "નિકાસ નિષ્ફળ",
  'dairy.export.lead': "નિકાસ પાછળથી, માંગેલા ક્રમમાં બનાવાય છે. તમારી બની રહી હોય ત્યાં સુધી આ પાનું કતારમાં તેનું સ્થાન બતાવે છે; ફાઇલ બન્યા પછી રસીદ બતાવે છે — ફાઇલનું નામ, હરોળની સંખ્યા, ચેકસમ, ક્યારે બની અને કોણે માંગી — અને પંદર મિનિટ ચાલતી ડાઉનલોડ લિંક. દરેક વખત લેવાની નોંધ રખાય છે.",
  'dairy.export.button': "નિકાસ",
  'dairy.export.hint': "આ પાનાના આંકડા CSV ફાઇલ તરીકે, પાછળથી બને છે. તમને કતાર પર લઈ જવાશે.",
  'dairy.export.state.queued': "તમારી નિકાસ કતારમાં છે. આગળની નિકાસ પૂરી થાય પછી તે બનશે.",
  'dairy.export.state.running': "તમારી નિકાસ હમણાં બની રહી છે.",
  'dairy.export.state.ready': "તમારી ફાઇલ તૈયાર છે.",
  'dairy.export.state.expired': "આ ફાઇલે સાત દિવસની મુદત વટાવી દીધી છે અને હવે અપાતી નથી. નીચેની રસીદ હજુ પણ શું બન્યું હતું તેનો રેકોર્ડ છે.",
  'dairy.export.state.failed': "આ નિકાસ બની શકી નહીં. તમારા રેકોર્ડમાં કંઈ ખોટું નથી — ફાઇલ બની નહીં, અને કારણ નીચે છે.",
