  'lessons.addLesson': "પાઠ ઉમેરો",
  'lessons.rule.title': "નિયમ.",
  'lessons.rule.body': "દરેક વિડિયો પાઠનું ફક્ત-ઑડિયો જોડિયું હોવું જ જોઈએ — 2G ફૉલબેક. ઑડિયોને પોતાના પાઠ તરીકે અપલોડ કરો અને વિડિયોના ફોર્મ પર જોડો.",
  'lessons.state.readOnly': "ફક્ત-વાંચવાની રૂપરેખા — આ કોર્સ બીજા પ્રશિક્ષકનો છે. તમે રૂપરેખા જોઈ શકો, બદલી નહીં શકો.",
