  'lessons.retry.refused': "બનાવ્યું નથી: “ફરી પ્રયાસ” — આ પ્લેટફોર્મ પર ફરી ચલાવવા માટે કોઈ પ્રોસેસિંગ જૉબ નથી. નિષ્ફળ સ્કૅનનો જવાબ નવો અપલોડ છે.",
