  'form.lesson.field.thumbnailAt': "થંબનેલ ફ્રેમ (mm:ss) પર",
  'form.lesson.field.chapters': "ચૅપ્ટર",
  'form.lesson.refusal.NO_AUTHOR': "તમારી પાસે course.author નથી, અને સામગ્રી ડેસ્ક ચાવી કોઈ પણ કોર્સ સંપાદિત કરે છે; બંને તમારા સત્ર પર નથી.",
  'form.lesson.refusal.NOT_OWNER': "આ બીજા પ્રશિક્ષકનો કોર્સ છે. ફક્ત તેનો લેખક કે સામગ્રી ડેસ્ક તેના પાઠ ઉમેરી/બદલી શકે.",
