  'live.declared': "આ પ્લેટફોર્મ કોઈ વિડિયો સ્ટ્રીમ ચલાવતું નથી. વર્ગ અહીં તમારી સહકારી મંડળીના પોતાના સમયમાં નક્કી થાય છે, તમે ચોંટાડેલી જોડાવાની લિંક પર લેવાય છે, તમે તેને સમાપ્ત ચિહ્નિત કરો છો, અને પછી રેકોર્ડિંગ જોડીને પાઠ તરીકે પ્રકાશિત થાય છે.",
