  'mutate.live.note.end': "વર્ગને સંપન્ન અને પૂરો ચિહ્નિત કરે છે. પછી તમે હાજરી નોંધી અને રેકોર્ડિંગ જોડી શકો.",
  'mutate.live.note.cancel': "નક્કી વર્ગ રદ કરે છે. નોંધાયેલા સભ્યોને આ પ્લેટફોર્મ જણાવતું નથી — શક્ય હોય તો જોડાવાની લિંક પર જણાવો.",
  'mutate.live.note.attendance': "હાજર રહેલા લોકોની સંખ્યા નોંધે છે, જેમ તમે ગણી. અગાઉની સંખ્યાને બદલે છે.",
  'mutate.live.note.recording': "તમારા મીડિયા બકેટમાંથી રેકોર્ડિંગ જોડે છે. રેકોર્ડિંગ પાઠ બને ત્યાં સુધી અગાઉનીને બદલે છે.",
  'mutate.live.note.to_lesson': "કોર્સના છેલ્લા મોડ્યુલના અંતે આ રેકોર્ડિંગ સાથે “લાઇવ” પ્રકારનો ડ્રાફ્ટ પાઠ બનાવે છે. એક વાર, અને ફક્ત ફાઇલ સાફ તપાસાય ત્યારે.",
  'mutate.live.refusal.NO_PERMISSION': "તમારી પાસે આ ક્રિયાની ચાવી નથી (પ્રશિક્ષકો પોતાના વર્ગો પર; સામગ્રી ડેસ્ક કોઈ પણ પર).",
