  'mutate.live.refusal.PROVIDER_NOT_CONFIGURED': "આ પ્લેટફોર્મ પર કોઈ વિડિયો પ્રદાતા ગોઠવાયેલ નથી (provider_not_configured). વર્ગ જોડાવાની લિંક પર લો અને પછી સમાપ્ત ચિહ્નિત કરો.",
