  'earnings.state.emptyHint': "તમે શીખવેલા અભ્યાસક્રમોની રોયલ્ટી પહેલી સવેતન નોંધણીથી અહીં દેખાશે. મફત અભ્યાસક્રમો શીખનારા નોંધે છે, પૈસા નહીં.",
  'earnings.state.noProfile': "સ્ટુડિયો ઍક્સેસ જરૂરી — તમારી હજી કોઈ પ્રશિક્ષક પ્રોફાઇલ નથી. પહેલાં એક બનાવો; કમાણી પ્રશિક્ષક રેકોર્ડની હોય છે.",
  'earnings.state.restricted': "કમાણી ફક્ત પ્રશિક્ષક અને નાણાં ડેસ્ક માટે છે. આ રકમો ફક્ત પ્રશિક્ષક અને ટેનન્ટ નાણાં ડેસ્ક જોઈ શકે છે.",
  'earnings.state.notEnabled': "ફ્લેગ બંધ — કમાણી અક્ષમ. આ મોડ્યુલ આ ટેનન્ટ કે પ્લાન માટે બંધ છે. કશું તૂટ્યું નથી અને કશું ખોવાયું નથી: ચોપડો દરેક લીટી રાખે છે; પાનું ફક્ત સક્ષમ નથી.",
