  // ---- PC-56 TENANT-8a · THE OVERRIDE (W180 · W181 · W182 + the template/templates form and mutate chains) ----
  'nav.templates': 'ટેમ્પલેટ',
  'templates.title': 'સૂચના ટેમ્પલેટ',
  'templates.new': 'નવો ફેરફાર',
  'templates.lead': 'પ્લેટફોર્મના ડિફોલ્ટ શબ્દો, જે તમે દરેક ઇવેન્ટ × ચેનલ × ભાષા માટે બદલી શકો છો — તમારો મંજૂર ફેરફાર તમારા સભ્યો માટે લાગુ થાય છે. સુરક્ષા સંદેશ (OTP, વિવાદ અને દરેક એવી ઇવેન્ટ જેમાંથી સભ્ય બહાર ન નીકળી શકે) પ્લેટફોર્મના નિયંત્રણમાં છે.',
  'templates.fallbackNeverSilence': 'ફેરફાર હટાવવાથી ઇવેન્ટ ક્યારેય ચૂપ થતી નથી — મોકલવાનું પ્લેટફોર્મના ડિફોલ્ટ પર પાછું આવે છે. જ્યાં ડિફોલ્ટ નથી, તે ચેનલ "કોઈ ટેમ્પલેટ નથી" નોંધે છે, અને આ પેજ એ જ કહે છે.',
