  'templates.provider.none': 'કોઈ બાહ્ય નોંધણી નથી: તમારા તપાસનારની મંજૂરીથી આ શબ્દો ચાલુ થાય છે.',
  'templates.provider.dlt': 'SMS ના શબ્દો મોકલતા પહેલાં DLT માં નોંધાયેલા હોવા જોઈએ. તમારા તપાસનારની મંજૂરી આ આવૃત્તિને પ્રદાતા પાસે મોકલે છે (સ્થિતિ "પ્રદાતા પાસે") અને તે અહીંથી ક્યારેય ચાલુ થતી નથી; DLT નોંધણી પ્લેટફોર્મ ડેસ્કનું કામ છે, અને ત્યાં સુધી અગાઉના શબ્દો મોકલાતા રહે છે.',
  'templates.provider.whatsapp': 'WhatsApp ના શબ્દો Meta દ્વારા મંજૂર થવા જોઈએ, અને આ પ્લેટફોર્મ પર કોઈ WhatsApp પ્રદાતા છે જ નહીં. તમારા તપાસનારની મંજૂરી શબ્દોને "પ્રદાતા પાસે" નોંધે છે; તે મોકલાશે નહીં.',
  'templates.status.locked': 'લૉક — સુરક્ષા સંદેશ',
  'templates.status.serving': 'તમારો ફેરફાર ચાલુ',
