  'templates.act.retire': 'ફેરફાર હટાવો (પ્લેટફોર્મ ડિફોલ્ટ પર પાછા)',
  'templates.actDone.submit': 'જમા થયું. મંજૂરીની પરવાનગી ધરાવતી બીજી વ્યક્તિ હા કહે ત્યારે જ તે ચાલુ થશે.',
  'templates.actDone.approve': 'મંજૂર. આગલી વખતથી તમારા સભ્યોને આ જ શબ્દો મળશે; જૂની આવૃત્તિ બદલાઈ.',
  'templates.actDone.approveToProvider': 'તમે મંજૂર કર્યું અને પ્રદાતાને મોકલ્યું. તે ચાલુ નથી: હજી કોઈ પ્રદાતા નોંધણી નથી, અને અગાઉના શબ્દો મોકલાતા રહેશે.',
  'templates.actDone.reject': 'અસ્વીકાર કર્યું. લેખક તમારી નોંધ ટેમ્પલેટ પર વાંચશે; મોકલાતા શબ્દો બદલાયા નથી.',
  'templates.actDone.withdraw': 'પાછું ખેંચ્યું. તમે નવી આવૃત્તિ લખી શકો છો.',
  'templates.actDone.retire': 'હટાવ્યું. આગલી વખતથી તમારા સભ્યોને પ્લેટફોર્મ ડિફોલ્ટ મળશે — અથવા, જ્યાં તે નથી, તે ચેનલ "કોઈ ટેમ્પલેટ નથી" નોંધશે.',
  'templates.refused.sendTest': '"મારા ફોન પર ટેસ્ટ મોકલો" બન્યું નથી: ટેનન્ટ પાસે ચકાસવા માટે કોઈ સાચો મોકલવાનો રસ્તો નથી (નોટિફાયર અહીં જોડાયેલો નથી), અને DLT માં નોંધાયા ન હોય તેવા શબ્દો પર ટેસ્ટ SMS ઑપરેટર પર અટકી જશે. નીચેનું પૂર્વાવલોકન પ્લેટફોર્મનું પોતાનું રેન્ડર છે.',
  'templates.refused.experiment': '"નવો પ્રયોગ" બન્યું નથી: કોઈ પ્રયોગ કોષ્ટક નથી (DELTA-029) — નોંધવા માટે કોઈ વેરિએન્ટ વહેંચણી, એક્સપોઝર ગણતરી કે વિજેતા નથી.',
  'templates.refused.dltReverify': '"ફેરફાર આગલી વખત પહેલાં DLT ફરી ચકાસે છે" પ્લેટફોર્મ ડેસ્કનું કામ છે: ટેનન્ટ DLT માં જમા કરી શકતો નથી. અહીં સાચું એ છે: SMS ફેરફાર આ કન્સોલથી ક્યારેય ચાલુ થતો નથી, તેથી અગાઉના શબ્દો મોકલાતા રહે છે.',
  'templates.refused.deliveryStats': 'અહીં માપાતું નથી: દરેક ટેમ્પલેટ આવૃત્તિની ડિલિવરી નોંધાતી નથી, અને તમારી મંડળીનો ડિલિવરી લૉગ અલગ પેજ છે (હજી બન્યો નથી).',
  'templates.refused.draftHistoryCanon': 'ડ્રાફ્ટ જ આવૃત્તિઓ છે: દરેક રાખવામાં આવે છે, કોણે લખ્યું અને કોણે નક્કી કર્યું તેની સાથે.',
  'templates.refused.compiledCache': 'કોઈ "કમ્પાઇલ્ડ કૅશ" નથી: મોકલવાનું મંજૂર આવૃત્તિ સીધી ડેટાબેઝમાંથી વાંચે છે, તેથી પેજ લોડ ન થવાથી મોકલાતા શબ્દો પર કોઈ અસર નથી.',
  'templates.refused.retryPageLoad': '"ફરી પ્રયાસ" પેજ ફરી ખોલવાનું છે, કોઈ કાર્ય નહીં: તમારા વતી કંઈ ફરી કરવામાં આવતું નથી.',
  'templates.editor.title': 'ટેમ્પલેટ',
  'templates.editor.pickEvent': 'ઇવેન્ટ પસંદ કરો',
  'templates.editor.since': '{date} થી ચાલુ',
  'templates.editor.lead': 'નીચે પ્લેટફોર્મ ડિફોલ્ટ છે; તમારો મંજૂર ફેરફાર તમારા સભ્યો માટે લાગુ થાય છે. વેરિએબલ ઇવેન્ટ નક્કી કરે છે — તમે શબ્દો ફેરવો છો, ડેટા ઘડતા નથી.',
  'templates.editor.locked': 'આ સુરક્ષા સંદેશ છે (સભ્ય તેમાંથી બહાર ન નીકળી શકે, અથવા તે ગંભીર છે): તેના શબ્દો પ્લેટફોર્મના નિયંત્રણમાં છે અને બદલી શકાતા નથી. ફક્ત સંદર્ભ માટે બતાવ્યું.',
