  'notif.center.lead': 'આ સહકારી સંસ્થામાં તમને મોકલાયેલી દરેક સૂચના, સંસ્થાના દિવસો મુજબ. દરેક સૂચનાની એક લાઇન: એપ-સૂચના, અને તેની બીજી ચેનલોનું શું થયું.',
  'notif.center.scoped': 'આ તમારું અંગત ઇનબોક્સ છે — આખી સંસ્થાની કોઈ યાદી નથી. ફિલ્ટર ફક્ત તમારી પોતાની સૂચનાઓ જ ગાળે છે.',
  'notif.center.deliveryUnaffected': 'ડિલિવરી પર અસર નથી — ફક્ત આ યાદી લોડ ન થઈ.',
  'notif.center.zero': 'હજુ અહીં કંઈ નથી. કેન્દ્ર ત્યારે જ બોલે છે જ્યારે ખરેખર તમારી જરૂર હોય.',
  'notif.center.noMatch': 'આ ફિલ્ટરોથી કોઈ સૂચના મળતી નથી. ગંભીર સૂચનાઓ તેમની ચેનલોમાંથી ક્યારેય ગળાતી નથી — ફક્ત આ દૃશ્યમાંથી.',
  'notif.center.caption': 'તમારી સૂચનાઓ, સૌથી નવી પહેલાં. સમય સંસ્થાના સમય-ઝોનમાં છે.',
  'notif.center.retention': 'કેન્દ્ર એ જ બતાવે છે જે ડિલિવરી લૉગ રાખે છે: છ મહિના (આ લૉગનો સાચવવાનો નિયમ).',
  'notif.center.footer': 'તમે જે જુઓ છો તે ડિલિવરી લૉગ છે: દરેક વ્યક્તિ × ઇવેન્ટ × ચેનલની એક લાઇન. આ પાના પર {n} એપ-સૂચનાઓ; તેમની બીજી ચેનલો દરેક ડિલિવરી વિગતમાં છે.',
