  'notif.ladder.back': '← સૂચના કેન્દ્ર પર પાછા',
  'notif.ladder.notFound': 'સૂચના મળી નથી. તે ડિલિવરી લૉગની મુદત વટાવી ગઈ હોય, કે લિંક તૂટેલી હોય.',
  'notif.ladder.restricted': 'તમારી પોતાની સૂચનાઓની વિગત તમે હંમેશાં જોઈ શકો. બીજા સભ્યની વિગત માટે સંચાલન-અધિકાર જોઈએ, જે આ કન્સોલમાં નથી.',
  'notif.ladder.sendHappened': 'મોકલવાનું થઈ ગયું છે — ફક્ત આ દૃશ્ય લોડ ન થયું.',
  'notif.ladder.eventTime': '{at} એ લખાઈ. નીચેનો દરેક સમય તે ચેનલની પોતાની લાઇનમાંથી છે.',
  'notif.ladder.ungrouped': 'ડિલિવરી લૉગ ચેનલોને જોડતો થયો તે પહેલાં લખાઈ: ફક્ત આ ચેનલ બતાવી શકાય છે.',
  'notif.ladder.channels': 'આ સૂચનાની ચેનલો',
  'notif.ladder.timeNotRecorded': 'સમય નોંધાયો નથી',
  'notif.ladder.heldUntil': '{at} સુધી રોકાઈ',
  'notif.ladder.acceptedByNotifier': 'નોટિફાયરે સ્વીકારી (કેટલાક રસ્તા પર આનાથી આગળ ઑપરેટરની રસીદ આવતી નથી)',
  'notif.ladder.inappNote': 'એપ-સૂચના એ જ લાઇન છે: તે "મોકલાઈ" લખાય છે અને "વાંચેલી" બને છે. તે ક્યારેય "પહોંચી" થતી નથી.',
  'notif.ladder.noRetries': 'કોઈ ચેનલ નિષ્ફળ ગઈ નથી — ફરી પ્રયાસની જરૂર પડી નથી.',
  'notif.ladder.channelOff': 'એક ચેનલ "ન મોકલાઈ — તમે બંધ કરી" બતાવે છે: તે મોકલતી વખતે તમારી પોતાની પસંદ છે, નોંધાયેલી, કોઈ ચૂપ ખાલી જગ્યા નહીં.',
  'notif.ladder.heldNote': 'એક ચેનલ તમારા શાંત કલાકો માટે રોકાઈ છે. સમય પૂરો થતાં જ મોકલાશે — કંઈ છોડાયું નથી.',
  'notif.ladder.releaseStopped': 'એક ચેનલ તમારા શાંત કલાકો માટે રોકાઈ છે, અને છોડવાનું હમણાં બંધ છે (કટોકટી રોક). તે રાહ જુએ છે — કંઈ ખોવાતું નથી.',
  'notif.ladder.grounding': 'એક સૂચનાની બધી ચેનલો એક ડિલિવરી ચાવી વહેંચે છે, તેથી આ યાદી શોધ છે — સમય પરથી અનુમાન નહીં.',
  'notif.prefs.lead': 'દરેક ઇવેન્ટ, દરેક ચેનલ — ફક્ત તમારા માટે સચવાય છે, આખી સંસ્થા માટે નહીં.',
  'notif.prefs.noChange': 'કંઈ બદલાયું નથી — સમીક્ષાની જરૂર નથી.',
  'notif.prefs.tooMany': 'એક સમીક્ષામાં લઈ જવા માટે બહુ વધારે ફેરફાર. એક સાથે ઓછા સાચવો.',
  'notif.prefs.stillApply': 'તમારી છેલ્લી સાચવેલી પસંદગીઓ ડિલિવરી પર લાગુ છે — ફક્ત આ સંપાદક લોડ ન થયું.',
  'notif.prefs.defaultsActive': 'તમે હજુ કંઈ બદલ્યું નથી — આ પ્લેટફોર્મના ડિફોલ્ટ છે: ઇવેન્ટ જે ચેનલો પર મોકલાય છે તે બધી ચાલુ છે, અને લૉક ઇવેન્ટ બંધ થતી નથી.',
  'notif.prefs.yours': 'તમે {n} ચેનલ સેટિંગ બદલી છે; બાકી બધું પ્લેટફોર્મ ડિફોલ્ટ છે.',
  'notif.prefs.counts': '{events} નોંધાયેલી ઇવેન્ટ, તેમાં {critical} ગંભીર; {locked} બંધ કરી શકાતી નથી.',
  'notif.prefs.caption': 'કોઈ ચેનલ પર તે ઇવેન્ટ મેળવવા ટિક કરો. ડૅશનો અર્થ છે ઇવેન્ટ તે ચેનલ પર ક્યારેય મોકલાતી નથી; તાળાનો અર્થ છે તે બંધ કરી શકાતી નથી.',
  'notif.prefs.cellLabel': '{event} {channel} દ્વારા મેળવો',
  'notif.prefs.lockedReason': 'સલામતી, વિવાદ અને પૈસાની સૂચનાઓ બંધ કરી શકાતી નથી.',
  'notif.prefs.saveHint': 'સાચવવાથી તમે બદલેલાની સમીક્ષા ખૂલે છે. પુષ્ટિ સુધી કંઈ લખાતું નથી.',
  'notif.prefs.notBuilt': 'આ પ્લેટફોર્મ પર બન્યું નથી',
  'notif.routine.title': 'એક ચેનલ પૂરતી છે (સામાન્ય સૂચનાઓ)',
  'notif.routine.decidedOn': 'નક્કી (22 જુલાઈ 2026) અને ચાલુ: માહિતી અને પ્રચાર સૂચનાઓ એક મુખ્ય ચેનલ પર જાય છે — તમારી પહેલી ચાલુ ચેનલ — નિષ્ફળ જાય તો SMS. ગંભીર અને મહત્વની સૂચનાઓ હજુ દરેક ચેનલ પર જાય છે.',
