  'notif.refused.digest': 'બન્યું નથી: સારાંશ. કોઈ કામ સૂચનાઓને સાંજના સારાંશમાં જોડતું નથી — જે કૉલમ (batched_into) તે વાપરત, તે કશું લખતું નથી. દરેક સૂચના અલગ મોકલાય છે.',
  'notif.refused.collapse': 'બન્યું નથી: અપડેટની હારમાળાને એક લાઇનમાં સંકેલવી ("હારમાળા છુપાવો"). ડિલિવરી લૉગ પર કોઈ સંકેલવાની ચાવી નથી, તેથી દરેક અપડેટ પોતાની લાઇન છે.',
