  'notif.refused.approvalRoleLock': 'બન્યું નથી: મંજૂરી ભૂમિકાને કારણે પૈસા અને વિવાદ સૂચનાઓ લૉક કરવી. લૉક દરેક ઇવેન્ટ પર છે — લૉક ઇવેન્ટ કોઈ બંધ કરી શકતું નથી.',
  'notif.refused.teamReachability': 'બન્યું નથી: ટીમ એડમિન દ્વારા સભ્યોની ગંભીર પહોંચ જોવી. બીજા સભ્યની પસંદગીઓ જોવાનો કોઈ સ્ટાફ રસ્તો નથી.',
