  'notif.refused.popoverKeys': 'ઘંટડીની અંદર તીર-કીથી ફરવા સ્ક્રિપ્ટ જોઈએ, જે આ કન્સોલ મોકલતું નથી; Tab, Enter અને Escape કામ કરે છે.',
