  'pages.state.notEnabled': 'ફ્લેગ બંધ — તમારી સંસ્થા માટે પેજ ચાલુ નથી (ફીચર ફ્લેગ). કશું તૂટ્યું નથી; તે બંધ છે. પ્લાન સેટિંગ જુઓ.',
  'pages.state.restricted': 'પેજ પ્રતિબંધિત — પેજ લખવા માટે cms.pages.manage જોઈએ, પ્રકાશિત કરવા cms.pages.publish, અને નીતિ પેજ બીજી વ્યક્તિ પ્રકાશિત કરે છે.',
