  'pages.refused.memberReader': 'હજી કોઈ સ્ટોરફ્રન્ટ કે મોબાઇલ સ્ક્રીન આ પેજ વાંચતી નથી.',
  'pages.refused.archiveWhileOrders': 'લાગુ નથી: "ચાલુ ઓર્ડર જેની સાથે જોડાયેલા હોય તે નીતિ પેજ સંગ્રહિત ન થઈ શકે" — ઓર્ડર એ નોંધતા નથી કે તેઓ કયા પેજ આવૃત્તિ હેઠળ થયા.',
  'pages.refused.views': 'માપ્યું નથી: જોવાયાની સંખ્યા — પેજ કોઈ ગણતરી રાખતા નથી.',
  'pages.refused.deflection': 'માપ્યું નથી: ટિકિટ ટાળવી — પ્રશ્ન અને સહાય ટિકિટ વચ્ચે કોઈ જોડાણ નથી.',
  'pages.refused.selfServe': 'માપ્યું નથી: પ્રશ્નો પર જોવાયાની ગણતરી નથી અને ટિકિટ સાથે જોડાણ નથી, એટલે "ટિકિટ ન ખોલનારા દર્શકો" ગણી શકાતા નથી.',
  'pages.refused.topGap': 'બન્યું નથી: ટિકિટોમાંથી સૌથી મોટો અનુત્તરિત પ્રશ્ન — ટિકિટનો લખાણ ક્યાંય જૂથબદ્ધ થતો નથી.',
  'pages.refused.voicePlayback': 'બન્યું નથી: જવાબોનો અવાજ — પેજમાં કોઈ ઑડિયો નથી.',
  'pages.refused.financeRead': 'બન્યું નથી: ચુકવણીના જવાબોની નાણાં-ડેસ્ક ચકાસણી — પેજ પર બીજી વ્યક્તિનો એકમાત્ર નિયમ નીતિ-ચકાસનાર છે.',
  'pages.refused.englishGloss': 'પ્રશ્ન નીચે અંગ્રેજી અર્થ નથી: તે માટે અનુવાદ જોઈએ, અને અનુવાદનો સંસ્થા માટે રસ્તો નથી.',
  'pages.refused.unpublish': 'અલગ "અપ્રકાશિત" નથી: લાઇવ આવૃત્તિ સંગ્રહિત કરવી એ જ તેને હટાવવું છે, અને સ્ક્રીન કહે છે કે પછી શું મળશે.',
  'pages.refused.keptLocally': '"સ્થાનિક રીતે રાખ્યું; ફરી પ્રયાસ કરશે" — આ કન્સોલ એમ ચાલતું નથી: તમારું લખાણ ફોર્મની લિંકમાં ચાલે છે, એટલે ફોર્મ પર પાછા જતાં તે સચવાય છે.',
