  'bc.title': "જાહેરાતો",
  'bc.lead': "જાહેરાત તમારા સક્રિય સભ્યોને જાય છે — બધાને, અથવા એક ભૂમિકા ધરાવતા સભ્યોને — ઍપમાં સંદેશ તરીકે, અને જ્યાં સભ્યનું ઉપકરણ છે ત્યાં પુશ તરીકે. નીચેનું દરેક પરિણામ ડિલિવરી લૉગમાંથી વાંચેલું છે.",
