  'wa.editor.why': "કોઈ શ્રેણી, હેડર, ફૂટર, બટન કે પ્રતિ-ચલ નમૂનો નથી, Meta ને રજૂઆત નથી અને Meta તરફથી નકારનું કારણ નથી. વોટ્સએપ ઓવરરાઇડ સૂચના-ટેમ્પલેટ પ્લેન પર લખાય છે, જ્યાં તે “પ્રદાતા પાસે” રાહ જુએ છે અને ક્યારેય મોકલાતું નથી.",
