  'wa.broadcast.why': "કોઈ પ્રદાતા, માર્કેટિંગ ટેમ્પલેટ શ્રેણી, વોટ્સએપ ટેમ્પલેટ કે સભ્ય ઑપ્ટ-ઇન નોંધાયેલું નથી, એટલે “માર્કેટિંગ માટે ઑપ્ટ-ઇન” હિસાબ ગણી શકાતો નથી. સભ્યોને તમારી જાહેરાતો સાચી છે અને ઍપમાં જાય છે.",
