  'kyc.desk.state.notEnabled.title': "ફ્લેગ બંધ — કેવાયસી કેન્દ્ર બંધ",
  'kyc.desk.state.notEnabled.body': "આ મોડ્યુલ આ સંસ્થા/પ્લાન માટે બંધ છે (ફીચર ફ્લેગ). કંઈ તૂટ્યું નથી — તે ચાલુ નથી. પ્લાન સેટિંગ જુઓ.",
