  'auditor.chain.holds.audit_trail': "અવધિની દરેક ઑડિટ-ટ્રેલ પંક્તિ કર્તા, ભૂમિકા (અથવા \"નોંધાઈ નથી\"), કારણ અને ફેરફાર સાથે — વ્યક્તિગત વિગતો સ્ક્રીન જેમ છુપાવેલી.",
  'auditor.chain.holds.compliance_pack': "અવધિ માટે ગણાયેલો અનુપાલન પૅકનો એક વિભાગ, દરેક આંકડો તેના આધાર સાથે.",
  'auditor.chain.writes': "ખાતરી કરતાં એક કતાર પંક્તિ, એક ઑડિટ-ટ્રેલ પંક્તિ અને એક વાંચન-લૉગ પંક્તિ લખાય છે. કોઈ વ્યાવસાયિક ડેટા બદલાતો નથી.",
  'auditor.chain.changePeriod': "અવધિ બદલો",
  'auditor.chain.proceed': "આગળ વધો — એક્સપોર્ટ કતારમાં મૂકો",
  'auditor.chain.failure.EXPORT_PARAMS_INVALID': "અવધિ નકારાઈ (ફાઇલ વધુમાં વધુ 366 દિવસ; પૅક વિભાગ એક ત્રિમાસિક).",
  'auditor.chain.failure.EXPORT_TOO_MANY_OPEN': "તમારા પાંચ એક્સપોર્ટ પહેલેથી રાહમાં છે — એક પૂરો થાય ત્યાં સુધી રાહ જુઓ.",
  'auditor.chain.failure.EXPORT_PLANE_DISABLED': "આ સહકારી માટે એક્સપોર્ટ ચાલુ નથી.",
  'auditor.chain.failure.EXPORT_DATASET_UNKNOWN': "તે એક્સપોર્ટ અસ્તિત્વમાં નથી.",
  'auditor.chain.failure.AUDITOR_REALM_OFF': "આ સહકારી માટે ઑડિટર કન્સોલ બંધ છે.",
  'auditor.chain.failure.AUDITOR_SCOPE_ONLY': "આ એક્સપોર્ટ માટે ઑડિટરનાં વાંચન જોઈએ.",
  'auditor.chain.failure.FORBIDDEN': "જે વાંચનનો આ એક્સપોર્ટ છે, તે તમારી પાસે નથી.",
  'auditor.chain.failure.AUDITOR_READ_ONLY': "નકાર્યું: ઑડિટર સત્ર પોતાના એક્સપોર્ટ સિવાય કશું લખતું નથી.",
  'auditor.chain.failure.generic': "એક્સપોર્ટ કતારમાં મૂકી શકાયો નહીં. કશું બન્યું નથી.",
  'auditor.unsigned': "સહી વિનાનું — આ પ્લેટફોર્મ પર હજુ કોઈ સહી ચાવી નથી. રસીદનો sha256 કન્ટેન્ટ હૅશ છે (તે સાબિત કરે છે કે તમારી ફાઇલ એ જ છે જે બની), સહી નથી (તે સાબિત કરી શકતો નથી કે કોણે બનાવી).",
  'auditor.job.lead': "એક્સપોર્ટ પૃષ્ઠભૂમિમાં માગ્યા ક્રમમાં બને છે. આ પેજ કતારમાં સ્થાન, પછી રસીદ અને 15 મિનિટની ડાઉનલોડ લિંક બતાવે છે. દરેક ડાઉનલોડ નોંધાય છે.",
  'auditor.job.signedLink': "ડાઉનલોડ લિંક સહી કરેલી છે (HMAC, 15 મિનિટ); ફાઇલ નહીં.",
