  'auditor.purpose.other': "વાંચન",
  'auditor.refused.platformSignature': "સહી નથી: પ્લેટફોર્મ સહી ચાવી નથી, તેથી કોઈ એક્સપોર્ટ કે પૅક પર સહી કે \"ચકાસી શકાય\" ચિહ્ન નથી (સ્થાપકની ચાવી, હજુ જારી નથી).",
  'auditor.refused.sharedChain': "\"શરૂથી અંત સુધી હૅશ શૃંખલા અખંડ\" નો દાવો નથી: પ્લેટફોર્મ ખાતાં દરેક સહકારી વહેંચે છે અને પટ્ટામાં વહેંચાયેલાં છે, તેથી એક સહકારીમાંથી તેમની શૃંખલા ચકાસી શકાતી નથી.",
  'auditor.refused.recordedCheck': "આ સહકારી માટે કોઈ નિર્ધારિત તપાસ નોંધાઈ નથી — ઉપરની તપાસ હમણાં, આ જ વાંચને થઈ.",
  'auditor.refused.reversalsLinked': "\"બધા ઉલટાવ જોડાયેલા\" બતાવ્યું નથી: ખાતાવહી ઉલટાવથી મૂળ વ્યવહારની કોઈ કડી નોંધતી નથી.",
  'auditor.refused.numberingGaps': "\"ક્રમાંકમાં કોઈ ખાલી જગ્યા નથી\" નો દાવો નથી: નોંધ ક્રમાંક ડેટાબેઝ ક્રમ છે, જેમાં સ્વભાવે ખાલી જગ્યા હોય છે.",
  'auditor.refused.exceptionRegister': "આ પ્લેટફોર્મ પર કોઈ અપવાદ રજિસ્ટર નથી, તેથી \"ખુલ્લા અપવાદ\" અહીં સંખ્યા નથી.",
  'auditor.refused.accessWindow': "આ પ્લેટફોર્મ પર ઑડિટર ઍક્સેસની હજુ કોઈ સમાપ્તિ, નોંધાયેલો નિમણૂક-પત્ર કે ફેરફાર સૂચના નથી — રદ કરવું એટલે ભૂમિકા કાઢવી.",
  'auditor.refused.firmIdentity': "કોઈ નિમણૂક રેકોર્ડ ઑડિટ ફર્મનું નામ રાખતો નથી, તેથી કોઈ બતાવ્યું નથી.",
  'auditor.refused.pdfWatermark': "કોઈ PDF અને પ્રતિ-વપરાશકર્તા વૉટરમાર્ક નથી: એક્સપોર્ટ તંત્ર ફક્ત CSV લખે છે.",
  'auditor.refused.byteIdentical': "\"એ જ પ્રશ્ન ફરી ચલાવતાં બાઇટ-સમાન પરિણામ\" જીવંત રેકોર્ડ પર વચન નથી.",
  'auditor.refused.irn': "IRN / સ્વીકૃતિ: કોઈ ઈ-ઇન્વૉઇસિંગ એકીકરણ તેને લખતું નથી — જેમાં છે તેની ગણતરી બતાવી, માની નથી.",
  'auditor.refused.gstPayableTie': "gst_payable પ્લેટફોર્મ ખાતા સાથે જોડ્યું નથી: તે ખાતું દરેક સહકારી વહેંચે છે; બતાવેલો મેળ આ સહકારીનાં પોતાનાં ઇન્વૉઇસ સરવાળા છે.",
  'auditor.refused.ekycBlocked': "\"ઈ-KYC થી અટકેલી\" અરજીઓ ગણી નથી: યોજના અરજીથી ઈ-KYC નિર્ણયની કોઈ કડી નથી.",
  'auditor.refused.signAttest': "\"સહી અને પ્રમાણિત કરો\" ઉપલબ્ધ નથી: કોઈ પ્રમાણન રેકોર્ડ અને સહી ચાવી નથી. પૅક સહી વિના રહે છે.",
  'auditor.refused.quarterClose': "પૅક ત્રિમાસિક-સમાપ્તિએ બનતો નથી; જાહેર નાણાકીય વર્ષના ત્રિમાસિક માટે વાંચતી વખતે ગણાય છે.",
  'auditor.refused.retry': "અહીં \"ફરી પ્રયાસ\" એટલે પેજ ફરી લોડ કરવું — તે કોઈ ક્રિયા નથી અને કશું લખતું નથી.",
  // ---- PC-56 TENANT-9b · THE RESOLUTIONS (W198, W2741–W2747) ----
