  'res.empty.open.body': "સામાન્ય સભાઓ વચ્ચે રજિસ્ટર શાંત રહે છે — ઠરાવનો મુસદ્દો ગમે ત્યારે; મતદાનનો સમય બોર્ડ નક્કી કરે છે.",
  'res.empty.past.title': "હજી કોઈ ઠરાવ નથી",
  'res.empty.past.body': "બોર્ડે જે ઠરાવો પર મતદાન કરાવ્યું તે અહીં દેખાશે, દરેક પોતાના નક્કી થયેલા પરિણામ સાથે.",
  'res.how.title': "એપ મતદાન કેવી રીતે થાય છે",
  'res.how.1': "સૂચના: મતદાન ખૂલતાં જ દરેક સભ્યને એપમાં અને પુશ સૂચનાથી, તેની પોતાની ભાષા (અંગ્રેજી, હિન્દી, ગુજરાતી) માં જણાવાય છે.",
  'res.how.2': "મતપત્ર: એક ટૅપ; મતદાન બંધ થાય ત્યાં સુધી મત બદલી શકાય, પછી અંતિમ.",
  'res.how.3': "દરેક મત ઠરાવે જાહેર કરેલો વિકલ્પ છે (તરફેણ · વિરુદ્ધ · તટસ્થ), દરેક સભ્યનો એક — શેર મૂડી ઉમેરે છે, ક્યારેય વધારાના મત નહીં.",
  'res.passes.title': "જો પસાર થાય",
  'res.passes.body': "ડિવિડન્ડ અથવા સંરક્ષણ બોનસ સામાન્ય નાણાં માર્ગે ચાલે છે: ઠરાવનું સૂત્ર → દરેક સભ્યની રકમ → એક વ્યક્તિએ તૈયાર કરેલ અને બીજાએ પુષ્ટિ કરેલ ચુકવણી રન → ચુકવણી ડેસ્કની બે-વ્યક્તિ બૅચ મંજૂરી. ફક્ત એ જ ઠરાવ ચૂકવી શકે જેનું નોંધાયેલું પરિણામ \"પસાર\" છે; નિષ્ફળ મત નહીં.",
  'res.footer': "ઠરાવનું જીવન-ચક્ર નોંધાયેલું (કોણે ખોલ્યો, કોણે બંધ કર્યો, ક્યારે, કેમ) · બંધ થયા પછી મત અપરિવર્તનીય · પરિણામ દરેક સભ્યને એપમાં પ્રકાશિત.",
  'res.state.flaggedOff.title': "ઠરાવો અને મતદાન બંધ છે",
  'res.state.flaggedOff.body': "આ મોડ્યુલ આ સહકારી માટે બંધ છે (ફીચર ફ્લેગ). કશું તૂટ્યું નથી — તે ચાલુ નથી. યોજના સેટિંગ જુઓ.",
  'res.state.restricted.title': "મુસદ્દો બનાવવો મર્યાદિત છે",
  'res.state.restricted.body': "મુસદ્દો બનાવવો, મતદાન ખોલવું અને બંધ કરવું શાસન પરવાનગી માંગે છે. મત પોતે દરેક પાત્ર સભ્યનો છે — આ કન્સોલ ક્યારેય કોઈ માટે મત નાખતું નથી.",
  'res.state.notFound.title': "ઠરાવ મળ્યો નથી",
  'res.state.notFound.body': "આ સહકારીનો કોઈ ઠરાવ આ આઈડીનો નથી.",
  'res.state.error.title': "ઠરાવો લોડ થઈ શક્યા નથી",
  'res.state.error.body': "ઠરાવો હમણાં વાંચી શકાયા નથી. કશું બદલાયું નથી; નાખેલા મત સચવાયેલા છે.",
  'res.refused.smsVoice': "મોકલાતું નથી: સ્માર્ટફોન વગરના સભ્યો માટે SMS અને વૉઇસ કૉલ — આ પ્લેટફોર્મ પર કોઈ મંજૂર SMS ટેમ્પ્લેટ અને કોઈ વૉઇસ પ્રદાતા નથી.",
  'res.refused.noticePeriod': "લાગુ નથી: \"બંધ થવાના 14 દિવસ પહેલાં, પેટાનિયમ લઘુતમ\" — સૂચના ક્યારે મોકલાઈ તે નોંધાતું નથી, તેથી સૂચના અવધિ માપી શકાતી નથી.",
  'res.refused.voiceReadout': "બન્યું નથી: મતપત્રનું અવાજમાં વાંચન — કોઈ વૉઇસ પ્રદાતા નથી.",
  'res.refused.paperBallot': "બન્યું નથી: MCC કાઉન્ટર પર કાગળનો વિકલ્પ — કાગળના મતમાં કોણે કોના વતી નાખ્યો તે નોંધાવું જોઈએ, અને તે રેકોર્ડ હજી નથી.",
  'res.refused.board': "આ પ્લેટફોર્મ પર કોઈ બોર્ડ ભૂમિકા નથી: મુસદ્દો અને મતદાન ખોલવું કે બંધ કરવું શાસન પરવાનગી છે (ટેનન્ટ એડમિન પાસે).",
  'res.refused.boardElection': "બોર્ડ ચૂંટણીમાં ઉમેદવારોનાં નામ હોય છે, અને આ પ્લેટફોર્મ પર કોઈ ઉમેદવાર યાદી નથી — અહીં તેનો મુસદ્દો કે મતદાન થઈ શકે નહીં.",
  'res.refused.perLanguageText': "દરેક ઠરાવનો એક પાઠ: સભ્યોને જેમ લખ્યું છે તેમ જ દેખાય છે — ઠરાવના પોતાના શબ્દોનું ભાષા-વાર સંસ્કરણ નથી.",
  'res.refused.autoClose': "બંધ થવાના સમય પછી મત આપમેળે નકારાય છે, પણ ઠરાવ એક વ્યક્તિ બંધ કરે છે — બંધ કરવું પરિણામ નોંધે છે, અને પરિણામ કોઈનું નોંધાયેલું કાર્ય છે.",
  'res.refused.closingSoon': "કોઈ \"જલ્દી બંધ\" યાદ-સૂચના મોકલાતી નથી: મતદાન ખૂલતાં સૂચના અને બંધ થતાં પરિણામ મોકલાય છે.",
  'res.refused.memberApp': "સભ્ય મોબાઇલ એપમાં હજી મતપત્ર સ્ક્રીન નથી — સભ્યો સાઇન-ઇન રહીને આ જ કન્સોલના મતપત્રથી મત આપે છે.",
  'res.refused.payoutConsole': "ચુકવણી રન (તૈયાર કરો, પછી બીજી વ્યક્તિ પુષ્ટિ કરે) એક API કાર્ય છે; આ સ્ક્રીન કોઈ રન બટન બતાવતી નથી.",
  'res.refused.smsResult': "ચુકવણી પર \"ગુજરાતી SMS\" મોકલાતો નથી (કોઈ SMS ટેમ્પ્લેટ નથી); સભ્યોને એપ અને પુશથી જણાવાય છે.",
