  "esg.lead": "અહીં ESG રસીદો છે, વિશેષણો નહીં: આંકડો ત્યારે જ છપાય છે જ્યારે પ્રકાશિત પદ્ધતિ આ પ્લેટફૉર્મ પર નોંધાયેલા તથ્યને મળે. બાકીની દરેક પંક્તિ સાફ કહે છે કે પદ્ધતિ નથી, હજી કંઈ નોંધાયું નથી, કે કોઈ કાર્યક્રમ નથી — શૂન્ય ક્યારેય નહીં.",
