  "esg.byName.methodEditing": "પદ્ધતિઓ પ્લેટફૉર્મના રેકૉર્ડ છે: કોઈ સહકારી તેમને બદલતી નથી. કોઈ માપદંડ પર તમારા પોતાના શબ્દો પ્રકટીકરણ છે.",
  "esg.byName.complianceRole": "આ પ્લેટફૉર્મ પર કોઈ અનુપાલન કે નાણાં ભૂમિકા નથી. ESG વાંચવા ESG વાંચનની પરવાનગી જોઈએ; પ્રકટીકરણ લખવા પ્રકટીકરણની પરવાનગી.",
  "esg.byName.carbonCredits": "કાર્બન: કોઈ કાર્યક્રમ નોંધાયો નથી અને ખેતરોનો કોઈ આંકડો છપાતો નથી. પ્લેટફૉર્મ ક્રેડિટ જારી કરતું નથી કે વેચતું નથી.",
