  "esg.byName.streakBeyondWindow": "સળંગ ગણતરી માત્ર પદ્ધતિના સમયગાળાની અંદર; પ્લેટફૉર્મ ક્યારેય નોંધાયેલું દરેક ઠાલવણ તપાસતું નથી.",
