  "amb.state.restricted.body": "એમ્બેસેડરનું સંચાલન ambassador.manage થી થાય છે (ટેનન્ટ એડમિન, સપોર્ટ એજન્ટ). ચુકવણી ચલાવવા ambassador.payout જોઈએ — ફક્ત ટેનન્ટ એડમિન, કારણ ફરજિયાત છે.",
  "amb.state.notFound.title": "આવો કોઈ એમ્બેસેડર નથી",
  "amb.state.notFound.body": "આ સહકારી સંસ્થાના કોઈ એમ્બેસેડરની આ આઈડી નથી.",
  "amb.state.error.title": "એમ્બેસેડર લોડ ન થઈ શક્યા",
  "amb.state.error.body": "જે કમિશન પ્રવાહો જમા થાય છે (સક્રિયકરણ પર ઓનબોર્ડિંગ, વેચાણ કમિશન) તે સર્વર પર ચાલુ રહે છે. ફરી પ્રયાસ કરો.",
  "amb.refused.retry": "ફરી પ્રયાસ ફક્ત આ પાનું ફરી લોડ કરે છે; કંઈ બદલાતું નથી.",
  "amb.run": "સાપ્તાહિક કમાણી ચુકવણી",
  "amb.recruit": "એમ્બેસેડરની ભરતી કરો",
  "amb.lede": "ગામ-સ્તરનું વિકાસ તંત્ર: દરેક એમ્બેસેડર માટે વધુમાં વધુ 3 ક્લસ્ટર વિસ્તાર, ટ્રેની → જિલ્લા સંયોજક સુધીની શ્રેણી, અને આજે જમા થતા પ્રવાહોમાંથી કમિશન — રેફરલ સક્રિય થાય ત્યારે ઓનબોર્ડિંગ (હાથે કરાતું, નોંધાયેલું કામ) અને માલની કિંમત પર વેચાણ કમિશન, ખેડૂત દીઠ મર્યાદા સાથે.",
  "amb.refused.exclusivity": "ક્લસ્ટર વિશિષ્ટતા નોંધાતી નથી: બે એમ્બેસેડર એક જ વિસ્તાર પસંદ કરી શકે છે.",
  "amb.refused.reassignment": "કોઈ પુનઃસોંપણી નોંધાતી નથી: 60 દિવસ નિષ્ક્રિય રહેવાથી પણ આ પ્લેટફોર્મ પર ક્લસ્ટર બદલાતું નથી.",
  "amb.refused.training": "તાલીમની પ્રગતિ નોંધાતી નથી — ફક્ત તાલીમ પૂરી થઈ કે નહીં.",
  "amb.refused.uncoveredVillages": "આવરી ન લેવાયેલાં ગામ: નોંધાયેલું નથી (આ સંસ્થાનાં ગામોની યાદી રખાતી નથી).",
  'amb.refused.fridayRun': "શુક્રવારની ચૂકવણી તારીખ રનની પોતાની છે: જોબ દર ગુરુવારે 23:00 IST રન તૈયાર કરે છે, અને બીજા ટેનન્ટ એડમિનની પુષ્ટિ સુધી કંઈ ચૂકવાતું નથી.",
