  "amb.edit": "ફેરફાર કરો",
  "amb.footer.inactive": "\"60 દિવસ નિષ્ક્રિય\" એવા સક્રિય એમ્બેસેડરને ગણે છે જેમની છેલ્લી નોંધાયેલી પ્રવૃત્તિ — મુલાકાત, સહાયથી જોડાણ, કોઈના વતી લિસ્ટિંગ કે AePS ઘટના — અથવા, કંઈ ન હોય તો, તેમની નોંધણી 60 દિવસથી જૂની છે.",
  "amb.act.suspend": "સસ્પેન્ડ કરો",
  "amb.act.reinstate": "ફરી સક્રિય કરો",
  "amb.act.payout": "ચુકવણી કરો",
  "amb.actTitle": "એમ્બેસેડર ક્રિયા",
  "amb.act.rule.suspend": "સસ્પેન્શનથી આ એમ્બેસેડર ક્ષેત્રમાં કામ નહીં કરી શકે અને નવું કમિશન નહીં કમાય. અગાઉ જમા કમાણી બાકી રહેશે. કારણ ફરજિયાત છે.",
  "amb.act.rule.reinstate": "ફરી સક્રિય કરવાથી આ એમ્બેસેડર ફરી કામ કરી અને કમાઈ શકશે. કારણ વૈકલ્પિક છે અને આપ્યું હોય તો નોંધાય છે.",
  'amb.act.rule.payout': "આ દરેક બાકી કમાણી માટે એક-એમ્બેસેડર અપવાદ રન તૈયાર કરે છે (ફક્ત કમિશન — સ્ટાઇપેન્ડ સાપ્તાહિક રનમાં જાય છે). બીજો ટેનન્ટ એડમિન કમાણી રન સ્ક્રીન પર પુષ્ટિ ન કરે ત્યાં સુધી કંઈ ખસતું નથી.",
  'amb.act.payoutFunding': "આ કમિશન તમારી સહકારી મંડળીનું પોતાનું મુખ્ય વૉલેટ ચૂકવે છે (સ્થાપકનો નિર્ણય); પ્લેટફોર્મનું ફી ખાતું હવે ચૂકવતું નથી.",
  'amb.act.payoutVerb': "તૈયાર કરવા ambassador.payout.prepare જોઈએ; પુષ્ટિ માટે ambassador.payout (બીજો ટેનન્ટ એડમિન).",
  "amb.act.reason": "કારણ (ફરજિયાત)",
