  "amb.act.notOffered.payout": "ચૂકવવા જેવું કંઈ નથી: આ એમ્બેસેડરની કોઈ બાકી કમાણી નથી, અથવા તે સસ્પેન્ડ છે.",
  "amb.act.done.suspend": "સસ્પેન્ડ કર્યું. ઑડિટ ટ્રેલમાં તમારા કારણ સાથે નોંધ છે.",
  "amb.act.done.reinstate": "ફરી સક્રિય કર્યું. ઑડિટ ટ્રેલમાં નોંધ છે.",
  'amb.act.done.payout': "{amount}નો અપવાદ રન તૈયાર થયો ({n} લાઇન). બીજો ટેનન્ટ એડમિન પુષ્ટિ કરે ત્યારે ચૂકવણી થશે.",
  'amb.act.zeroSum': "પુષ્ટિ થયે દરેક એમ્બેસેડરને એક શૂન્ય-સરવાળા ટ્રાન્સફરમાં ચૂકવણી થાય છે: જેટલી રકમ તમારી મંડળીના મુખ્ય વૉલેટમાંથી જાય છે તેટલી જ તેમના વૉલેટમાં પહોંચે છે.",
  'amb.act.toEarnings': "કમાણી રન ખોલો",
  'amb.run.title': "સાપ્તાહિક કમાણી રન તૈયાર કરો",
  "amb.run.object": "આ સંસ્થામાં {amount} બાકી છે; {n} એમ્બેસેડર સક્રિય છે.",
  'amb.run.rule': "આ રન હમણાં તૈયાર કરે છે (જોબ પણ દર ગુરુવારે 23:00 IST તૈયાર કરે છે): બાકી કમાણી ધરાવતા દરેક સક્રિય એમ્બેસેડર, અને આખો મહિનો સક્રિય રહેલાનું માસિક સ્ટાઇપેન્ડ. બીજો ટેનન્ટ એડમિન પુષ્ટિ કરે ત્યાં સુધી કંઈ ખસતું નથી.",
  "amb.run.nothing": "હમણાં કંઈ બાકી નથી, એટલે ચલાવવા જેવું કંઈ નથી.",
