  "auc.moneyNote": "પૈસા: દરેક બોલીદારની EMD તેની પહેલી બોલીએ તેના વૉલેટમાં રોકાય છે. બંધ થતાં હારનારાઓની EMD પાછી આવે છે; વિજેતાની ઓર્ડરમાં લાગુ થાય છે, અને વિજેતાએ બાકી 48 કલાકમાં ચૂકવવાનું છે. ન ચૂકવે તો EMD વેચનારને જપ્ત થાય છે અને લૉટ ફરી વેચાણ પર આવે છે.",
  "auc.new.done": "નક્કી થઈ. તે તમે આપેલા સમયે આપમેળે ખૂલશે અને બંધ થશે.",
  "auc.new.doneListing": "લિસ્ટિંગ હવે હરાજી માટે રોકાઈ છે — હરાજી પૂરી થાય ત્યાં સુધી કોઈ સીધી ખરીદી શકતું નથી.",
  "auc.refusal.LISTING_REQUIRED": "હરાજી માટે લિસ્ટિંગ પસંદ કરો.",
  "auc.refusal.KIND_UNKNOWN": "અંગ્રેજી (ખુલ્લી) અથવા સીલબંધ પસંદ કરો — રિવર્સ અને ડચ બનેલ નથી.",
  "auc.refusal.START_INVALID": "શૂન્યથી ઉપર શરૂઆતનો ભાવ આપો, રૂપિયા એકમ દીઠ.",
  "auc.refusal.RESERVE_INVALID": "રિઝર્વ શૂન્યથી ઉપર રૂપિયાની રકમ હોવી જોઈએ.",
  "auc.refusal.RESERVE_BELOW_START": "રિઝર્વ શરૂઆતના ભાવથી ઓછું ન હોઈ શકે.",
  "auc.refusal.INCREMENT_INVALID": "લઘુત્તમ વધારો શૂન્યથી ઉપર રૂપિયાની રકમ હોવી જોઈએ.",
  "auc.refusal.EMD_INVALID": "EMD રૂપિયાની રકમ હોવી જોઈએ (ન હોય તો 0).",
  "auc.refusal.WINDOW_INVALID": "હરાજી ખૂલ્યા પછી જ બંધ થવી જોઈએ.",
  "auc.refusal.WINDOW_ENDED": "તે સમાપ્તિ સમય વીતી ગયો છે.",
  "auc.refusal.DECISION_WINDOW_INVALID": "વેચનારની નિર્ણય અવધિ 1 થી 72 કલાક છે.",
  "auc.refusal.CONSENT_CHANNEL_REQUIRED": "નોંધો કે વેચનારે કેવી રીતે સંમતિ આપી (અવાજ, OTP અથવા લેખિત).",
  "auc.refusal.CONSENT_EVIDENCE_REQUIRED": "અવાજ અથવા લેખિત સંમતિ સાથે પુરાવો જોઈએ (અપલોડ કરેલી મીડિયા id).",
  "auc.refusal.REASON_REQUIRED": "3–300 અક્ષરોનું કારણ આપો — તે શબ્દશઃ નોંધાય છે.",
  "auc.code.AUCTION_ENDED": "હરાજી સમાપ્ત થઈ છે — હવે બોલીઓ સ્વીકારાતી નથી.",
  "auc.code.AUCTION_ENTRY_PAUSED": "પ્રવેશ અટક્યો છે — નવા બોલીદારો હાલ જોડાઈ શકતા નથી.",
  "auc.code.REASON_REQUIRED": "3–300 અક્ષરોનું કારણ જરૂરી છે.",
  "auc.code.AUCTION_CONSENT_REQUIRED": "સ્ટાફના નિર્ણય માટે વેચનારની નોંધાયેલી સંમતિ જરૂરી છે.",
  "auc.code.AUCTION_CANCEL_LIVE_FORBIDDEN": "ફક્ત ટેનન્ટ એડમિન જ કારણ સાથે લાઇવ હરાજી રોકી શકે.",
  "auc.code.AUCTION_ACT_NOT_ALLOWED": "હરાજીની હાલની સ્થિતિમાં આ શક્ય નથી.",
  "auc.code.AUCTION_LISTING_UNAVAILABLE": "તે લિસ્ટિંગની હરાજી ન થઈ શકે — તે પ્રકાશિત નથી (કદાચ પહેલેથી હરાજીમાં છે).",
  "auc.code.AUCTION_FORBIDDEN": "તમને આ હરાજી પર આ કરવાની મંજૂરી નથી.",
  "auc.code.AUCTION_INVALID": "હરાજીની શરતો નકારાઈ — ભાવ અને સમય તપાસો.",
  "auc.code.AUCTION_ILLEGAL_TRANSITION": "આ થાય તે પહેલાં હરાજી આગળ વધી ગઈ.",
  "auc.code.AUCTION_CONCURRENCY": "એ જ ક્ષણે કોઈએ આ હરાજી બદલી — ફરી પ્રયાસ કરો.",
  "auc.code.AUCTION_ORDER_MISMATCH": "ઓર્ડર લૉટ મૂલ્ય સાથે મેળ ન ખાયો — કંઈ લખાયું નથી.",
  "auc.code.AUCTION_READ_FORBIDDEN": "બોલી પ્રવાહ વાંચવા auction.read અથવા auction.bid જોઈએ.",
  "auc.code.IDEMPOTENCY_IN_PROGRESS": "એ જ વિનંતી હજુ ચાલુ છે — થોડી રાહ જુઓ.",
  "auc.code.AUDITOR_READ_ONLY": "ઑડિટર ભૂમિકા ફક્ત વાંચે છે — કાર્ય કરી શકતી નથી.",
