  'lab.breadcrumb.labour': "મજૂરી",
  'lab.lede': "બુકિંગ 12 માંથી 7 સ્થિતિઓમાંથી પસાર થાય છે — ખુલ્લું, રોસ્ટર પાકું, ચાલુ, પૂર્ણ, ચૂકવાયું, રદ, સમાપ્ત ({unreachable} ક્યારેય આવતી નથી). સન્માનનું લઘુત્તમ વેતન નીતિ નહીં, ભૌતિકશાસ્ત્ર છે: ડેટાબેઝ વૈધાનિક લઘુત્તમથી ઓછું વેતન સ્વીકારતો જ નથી. ફક્ત-મહિલા, વાહન, ભોજન, શૌચાલય, પીવાનું પાણી અને મહિલા નિરીક્ષક કામ પર જાહેર થાય છે, અને કામદાર ઉમેરતી વખતે ફક્ત-મહિલા લાગુ થાય છે.",
