  'lab.kpi.median.no_job_fully_filled_in_30d': "ભરવાનો મધ્ય સમય — 30 દિવસમાં કોઈ કામ પૂરું ભરાયું નથી",
  'lab.kpi.restricted': "મજૂરીના આંકડા માટે લેબર ડેસ્ક અધિકાર જોઈએ (labour.desk અથવા booking.manage).",
  'lab.kpi.error': "મજૂરીના આંકડા લોડ ન થયા. પેજ ફરી ખોલો.",
  'lab.state.flaggedOff.title': "બંધ — મજૂરી કામ નિષ્ક્રિય",
  'lab.state.flaggedOff.body': "આ મોડ્યુલ આ સંસ્થા/યોજના માટે બંધ છે (ફીચર ફ્લેગ). કંઈ તૂટ્યું નથી — તે ચાલુ નથી. યોજના સેટિંગ જુઓ.",
