  'ak.list.lede': 'તમારા ડેટા સુધી પ્રોગ્રામથી પહોંચ. કી ફક્ત એક જ વાર, બનાવતી વખતે બતાવાય છે અને ફક્ત sha256 હેશ તરીકે સંગ્રહાય છે — પ્લેટફોર્મ સહિત કોઈ તેને પાછી વાંચી શકતું નથી. સ્કોપ ચોક્કસ મંજૂરી-યાદીઓ છે: કી બરાબર એ જ કરે છે જે લખ્યું છે, વધુ નહીં, અને તેને બનાવનાર વ્યવસ્થાપકથી વધુ ક્યારેય નહીં. ફક્ત લાઇવ કી છે — આ પ્લેટફોર્મ પર સેન્ડબોક્સ મોડ નથી.',
