  'swb.run.rule.prepare': "આ અઠવાડિયાનો રન હમણાં તૈયાર કરે છે: દરેક સક્રિય એમ્બેસેડરની અત્યાર સુધીની બાકી કમાણી, અને આખો મહિનો સક્રિય રહેલાનું સ્ટાઇપેન્ડ. કંઈ ખસતું નથી; ભંડોળ મુખ્ય વૉલેટમાંથી વંચાય છે.",
  'swb.run.rule.confirm': "પુષ્ટિ કરવાથી રનની હમણાં ચૂકવણી થાય છે: મુખ્ય વૉલેટમાંથી દરેક એમ્બેસેડરને એક ટ્રાન્સફર. જે લાઇન વૉલેટ આવરી ન શકે તે ઘટ સાથે ભંડોળ વિના ચિહ્નિત થાય છે — તેના માટે કંઈ ખસતું નથી. તમે તૈયાર કરનાર વ્યક્તિ ન હોવા જોઈએ.",
  'swb.run.rule.pay': "ફક્ત હજી બાકી લાઇનો (ભંડોળ વિના કે નિષ્ફળ)ની મુખ્ય વૉલેટની હાલની સ્થિતિમાંથી ચૂકવણી કરે છે. ચૂકવાયેલી લાઇનો ક્યારેય બે વાર ચૂકવાતી નથી.",
  'swb.run.rule.refuse': "અસ્વીકાર કરવાથી કંઈ ચૂકવ્યા વગર રન બંધ થાય છે. કમાણી બાકી રહે છે અને આગામી રન તેને લે છે.",
  'swb.run.notOffered.prepare': "એક રન પહેલેથી ખુલ્લો છે — પહેલાં તેની પુષ્ટિ, ચૂકવણી કે અસ્વીકાર કરો.",
  'swb.run.notOffered.confirm': "આ રન હમણાં તમારા દ્વારા પુષ્ટિ પામી શકતો નથી: તે તૈયાર નથી, અથવા તમે તેને તૈયાર કર્યો.",
  'swb.run.notOffered.pay': "ફક્ત આંશિક કે ભંડોળ વિનાનો રન ફરી ચૂકવાય છે — અને ક્યારેય તૈયાર કરનાર દ્વારા નહીં.",
