  'swb.run.refused.dairyCycle': "\"ડેરી ચક્ર સાથે ચૂકવણી\" બન્યું નથી: રનનું પોતાનું સાપ્તાહિક ચક્ર છે, દૂધ ચૂકવણી સાથે કોઈ જોડાણ નથી.",
  'swb.run.refused.proRata': "સ્ટાઇપેન્ડ ફક્ત આખા મહિનાનું ચૂકવાય છે: મહિના દરમિયાન નોંધાયેલા કે સસ્પેન્ડ થયેલા એમ્બેસેડરને તે મહિનાનું મળતું નથી (પ્રમાણસર બન્યું નથી).",
  'swb.run.refused.retry': "ફરી પ્રયાસ આ પેજ ફરી લોડ કરે છે; કંઈ બદલાતું નથી.",
  'swb.att.title': "હાજરી સમીક્ષા",
