  'swb.att.lede': "ખેતરથી {m} મી.થી વધુ દૂરનું ક્લૉક-ઇન નોંધાય છે અને સમીક્ષા માટે ચિહ્નિત થાય છે, ક્યારેય ના પાડવામાં આવતું નથી. દિવસની પુષ્ટિ સુધી કોઈ મજૂરી બનતી નથી.",
  'swb.att.law': "ડેટાબેઝ દ્વારા લાગુ: કોઈ મજૂર પોતાના દિવસની પુષ્ટિ કે ખાતરી ક્યારેય કરી શકતો નથી; સમીક્ષા માટે ચિહ્નિત દિવસ ખાતરી વિના ક્યારેય પુષ્ટિ પામતો નથી; જેણે કાગળનો દિવસ નોંધ્યો તે તેની ખાતરી આપી શકતો નથી.",
