  'swb.att.act.confirm_clean': "બધા સ્વચ્છ રેકોર્ડ પુષ્ટિ કરો",
  'swb.att.act.backfill': "કાગળની નોંધ",
  'swb.att.rule.vouch': "તમે ખાતરી આપો છો કે આ દિવસ નોંધ પ્રમાણે કામ થયું, ભલે ક્લૉક-ઇન સીમાની બહાર (કે કાગળ પર) હતું. જે જોયું તે લખો — 10 થી 500 અક્ષર. પછી દિવસ પુષ્ટિ પામી શકે.",
  'swb.att.rule.refuse': "અસ્વીકારનો અર્થ છે આ દિવસ ક્યારેય ચૂકવાશે નહીં. કારણ લખો — 10 થી 500 અક્ષર.",
  'swb.att.rule.confirm': "પુષ્ટિથી 18:00 IST મજૂરી રન આ દિવસની ચૂકવણી કામના એસ્ક્રોમાંથી કરી શકે છે. મજૂર પોતાના દિવસની પુષ્ટિ ક્યારેય કરી શકતો નથી.",
  'swb.att.rule.confirm_clean': "તમે પુષ્ટિ કરી શકો તે કામોના દરેક સ્વચ્છ દિવસ (સીમાની અંદર સ્વ ક્લૉક-ઇન, ક્લૉક-આઉટ થયું)ની પુષ્ટિ કરે છે — દરેક દિવસ અલગથી, પોતાની ઑડિટ નોંધ સાથે. તમારા પોતાના દિવસો છોડી દેવાય છે.",
  'swb.att.rule.backfill': "સહી કરેલી કાગળની શીટમાંથી એક દિવસ નોંધે છે. તે \"સમીક્ષા જરૂરી\" તરીકે બને છે: બીજી વ્યક્તિ (નોકરીદાતા કે સમીક્ષક) ખાતરી આપી પુષ્ટિ કરે છે. 10–500 અક્ષરનું કારણ જરૂરી છે.",
  'swb.att.done.vouch': "ખાતરી અપાઈ. હવે દિવસ પુષ્ટિ પામી શકે.",
