  'swd.code.IDEMPOTENCY_CONFLICT': "આ પહેલેથી અલગ મૂલ્યો સાથે મોકલાયું હતું; ફરી લોડ કરો અને પ્રયાસ કરો.",
  'swd.code.NOT_FOUND': "મળ્યું નથી.",
  'swd.code.unknown': "કાર્ય એવા કારણથી નિષ્ફળ ગયું જે કન્સોલ ઓળખતું નથી.",
  'swd.agm.method.gmv': "GMV = નાણાકીય વર્ષમાં પૂર્ણ થયેલા દરેક ઓર્ડરનું માલ મૂલ્ય (ઓર્ડર પેટા-સરવાળો, ડિલિવરી, ફી અને કર પહેલાં). પૂર્ણ થયા પછી રિફંડ કે રદ થયેલા ઓર્ડર ગણાતા નથી. સ્રોત: ઓર્ડર.",
  'swd.agm.method.paid_to_members': "સભ્યોને ચુકવણી = વર્ષમાં escrow_release હેઠળ સભ્યોના મુખ્ય વૉલેટમાં નોંધાયેલી લેજર એન્ટ્રીઓનો ચોખ્ખો સરવાળો: ઓર્ડર પતાવટ જમા છે, વિવાદ અને પરત વસૂલાત ઉધાર છે. સ્રોત: લેજર.",
  'swd.agm.method.paid_share': "હિસ્સો = સભ્યોને ચુકવણી ÷ GMV, બંને દર્શાવેલ, એક જ ચલણમાં (બેસિસ પોઇન્ટ, નીચે તરફ પૂર્ણાંકિત). બે તથ્યોનો ગુણોત્તર.",
  'swd.agm.method.platform_fees': "પ્લેટફોર્મ ફી = વર્ષમાં આ મંડળીના ઓર્ડર પતાવટ અને વસૂલાતથી પ્લેટફોર્મ ફી ખાતામાં નોંધાયેલી ચોખ્ખી રકમ. સ્રોત: લેજર.",
  'swd.agm.method.gst_on_commission': "કમિશન પર GST = વર્ષમાં આ મંડળીના ઓર્ડર પતાવટથી પ્લેટફોર્મ GST-ચૂકવવાપાત્ર ખાતામાં નોંધાયેલી ચોખ્ખી રકમ. સ્રોત: લેજર.",
  'swd.agm.method.tenant_commission': "મંડળી કમિશન = વર્ષમાં ઓર્ડર પતાવટથી આ મંડળીના પોતાના કમિશન ખાતામાં નોંધાયેલી ચોખ્ખી રકમ. સ્રોત: લેજર.",
  'swd.agm.method.surplus': "FPO પૂરાંત આપવામાં આવી નથી: પ્લેટફોર્મ મંડળીના સંચાલન ખર્ચનું કોઈ લેજર રાખતું નથી, તેથી તથ્યોમાંથી પૂરાંત ગણી શકાતી નથી. ઓડિટ થયેલા હિસાબ જુઓ.",
  'swd.agm.method.operating_costs': "સંચાલન ખર્ચ આપવામાં આવ્યો નથી: પ્લેટફોર્મ પર કોઈ ખર્ચ લેજર નથી. મંડળીના પોતાના ચોપડા (અને તેના ઓડિટર) સ્રોત છે.",
  'swd.agm.method.statements': "નાણાકીય વર્ષ સાથે મેળ ખાતા સમયગાળાના પતાવટ પત્રકો, જે સભ્યોને આપવામાં આવ્યા. દરેક સભ્ય પત્રક પેજ પર પોતાનું વાંચે છે.",
  'swd.agm.method.snapshot': "વર્ષના અંતે શેર રજિસ્ટર: ત્યારે હાજર અને ત્યાર પછી ન બદલાયેલી પંક્તિઓ. કોઈ બદલાઈ હોય તો અંશ આપવામાં આવતો નથી — રજિસ્ટર ઇતિહાસ રાખતું નથી.",
  'swd.agm.method.closed_in_fy': "નાણાકીય વર્ષમાં બંધ થયેલા ઠરાવો, બંધ થતી વખતે નોંધાયેલા પરિણામ સાથે (ત્યારે નોંધાયેલ કોરમ અને બહુમતી).",
  'swd.agm.method.annexure': "ઓડિટરનો અહેવાલ, જેમ મંડળીએ અપલોડ કર્યો — પ્લેટફોર્મે બનાવ્યો કે તપાસ્યો નથી.",
  'swd.agm.method.quorum': "કોરમ, જેમ governance.quorum_bp સેટિંગમાં નોંધાયેલું છે (મંડળીનું પોતાનું, અથવા ન હોય તો પ્લેટફોર્મનું ડિફોલ્ટ).",
  'swd.agm.method.notice_period': "AGM નોટિસ સમયગાળો આપવામાં આવ્યો નથી: પ્લેટફોર્મ પર તેનું કોઈ પેટાનિયમ સેટિંગ નથી, અને યાદથી લખેલી સંખ્યા ડેટા નથી.",
